L5_1.m_Face = "UNIT_PRIDE"
L5_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L5_1.m_Pos = "R_M_I"
L5_1.m_Talk_KOREA = "예상대로야. 녀석은 주말에 서식지를 벗어나는 법이 없거든."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "予想どおりだな。やつは週末は住処から出ないんだ。"
L5_1.m_Talk_ENG = "As anticipated. She never leaves her habitat on the weekend."
L5_1.m_Talk_TWN = "跟我想的一樣。那傢伙週末從來不離開她的被窩。"
L5_1.m_Talk_THA = "ตามที่คาดการณ์ไว้ เธอไม่เคยออกจากที่พักในช่วงสุดสัปดาห์"
L5_1.m_Talk_VTN = "Đúng như dự đoán. Cô ấy chẳng bao giờ rời khỏi môi trường sống của mình vào cuối tuần."
L5_1.m_Talk_SCN = "跟预想的一样。那家伙周末从来不离开她的窝。"
L5_1.m_Talk_DEU = "Wie erwartet. Am Wochenende verlässt sie nie ihre gewohnte Umgebung."
L5_1.m_Talk_FRA = "Comme prévu, elle ne quitte jamais son habitat le week-end..."
