L7_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L7_1.m_Pos = "L"
L7_1.m_Talk_KOREA = "고무 장갑과 방패로 쓸 냄비 뚜껑을 가져 왔어요."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "ゴム手袋と、盾に使う鍋のフタを持ってきました。"
L7_1.m_Talk_ENG = "I have rubber gloves and a pot lid for protection."
L7_1.m_Talk_TWN = "我帶來橡膠手套和當作盾牌的鍋蓋。"
L7_1.m_Talk_THA = "ฉันมีถุงมือยางและฝาหม้อเพื่อป้องกัน"
L7_1.m_Talk_VTN = "Tôi có găng tay cao su và nắp nồi để làm khiên."
L7_1.m_Talk_SCN = "我带来了橡胶手套和作盾牌的锅盖。"
L7_1.m_Talk_DEU = "Ich habe Gummihandschuhe und einen Topfdeckel zum Schutz mitgebracht."
L7_1.m_Talk_FRA = "J'ai des gants en caoutchouc et un couvercle de casserole pour me protéger."
