L11_1 = {}
L11_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5400401
L11_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Action = "SELECT"
L11_1.m_ActionStrKey = "MARK1"
L11_1.m_Talk_KOREA = "주말 아침부터 왜 이러는지 설명해 주겠나?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "週末の朝からどうしてこんなことをしているのか、説明してくれないか？"
L11_1.m_Talk_ENG = "Will anyone explain what is going on?"
L11_1.m_Talk_TWN = "二位能解釋一下，週末一大早的是在做什麼嗎？"
L11_1.m_Talk_THA = "มีใครบอกได้ไหมไว่าเกิดอะไรขึ้น?"
L11_1.m_Talk_VTN = "Ai đấy sẽ giải thích chuyện gì được không?"
L11_1.m_Talk_SCN = "两位，能解释一下周末一大早的是在做什么吗？"
L11_1.m_Talk_DEU = "Kann mir mal jemand erklären, was hier los ist?"
L11_1.m_Talk_FRA = "Quelqu'un peut m'expliquer ce qu'il se passe ?"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5400401
L12_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_LAUGH"
L12_1.m_Action = "MARK"
L12_1.m_ActionStrKey = "MARK1"
L12_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L12_1.m_Pos = "R"
L12_1.m_Talk_KOREA = "경기 전날에는 푹 쉬면서 컨디션 조절하자는 게 코치의 아이디어 아니었어?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "試合の前日はゆっくり休みながら体調を整えようってのが、コーチの考えじゃなかったのか？"
L12_1.m_Talk_ENG = "Wasn't it your idea to rest well before match day, Coach?"
L12_1.m_Talk_TWN = "比賽前一天好好休息，調整狀態，這不是教練的意思嗎？"
L12_1.m_Talk_THA = "ไม่ใช่ความคิดของคุณหรอที่จะพักผ่อนให้เพียงพอก่อนวันแข่งขันเหรอ โค้ช?"
L12_1.m_Talk_VTN = "Không phải ý của ngài là nghỉ ngơi thật tốt trước ngày thi đấu sao, HLV?"
L12_1.m_Talk_SCN = "比赛前一天好好休息、调整状态，这不是教练的主意吗？"
L12_1.m_Talk_DEU = "War es nicht die Idee des Trainers, sich am Tag vor dem Spiel gut auszuruhen?"
L12_1.m_Talk_FRA = "Eh bien, tu nous as dit de nous reposer avant le match, pas vrai, Coach ?"
