L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Action = "SELECT"
L14_1.m_ActionStrKey = "MARK2"
L14_1.m_Talk_KOREA = "외식 가자는 말을 그렇게 받아들일 수도 있군."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "外食に行こうという話を、そんな風に受けとることもあるんだな。"
L14_1.m_Talk_ENG = "So that's how you understood eating out as."
L14_1.m_Talk_TWN = "呃，這個用作外出聚餐的理由可以是可以……"
L14_1.m_Talk_THA = "นั่นเป็นวิธีที่คุณเข้าใจว่าการรับประทานอาหารนอกบ้านเป็นยังไง"
L14_1.m_Talk_VTN = "Vậy hai người hiểu ăn ngoài như thế sao?"
L14_1.m_Talk_SCN = "呃，这个用作外出聚餐的理由可以是可以……"
L14_1.m_Talk_DEU = "So hast du es also verstanden, als ich vorgeschlagen habe, dass wir essen gehen."
L14_1.m_Talk_FRA = "Ah. C'est comme ça que vous avez compris « manger à l'extérieur» alors."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 5400401
L15_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_DESPAIR"
L15_1.m_Action = "MARK"
L15_1.m_ActionStrKey = "MARK2"
L15_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L15_1.m_Pos = "R"
L15_1.m_Talk_KOREA = "아무튼. 저번에 꼬맹이 반응은 코치도 봤잖아."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "とにかく。この前のおこちゃまの反応はコーチも見ただろ？"
L15_1.m_Talk_ENG = "Anyway, you saw how she reacted last time."
L15_1.m_Talk_TWN = "總之，上次小鬼的反應教練不是也有看到？"
L15_1.m_Talk_THA = "แล้ว คุณเห็นว่าเธอเป็นยังไงเมื่อคราวที่แล้ว"
L15_1.m_Talk_VTN = "Dù sao, lần trước ngài đã thấy nhóc ấy phản ứng ra sao rồi đấy"
L15_1.m_Talk_SCN = "总之，上次小不点的反应教练不也看到了嘛。"
L15_1.m_Talk_DEU = "Wie auch immer, du hast genau gesehen, wie sie letztes Mal reagiert hat."
L15_1.m_Talk_FRA = "Bref, t'as bien vu comme elle a réagit la dernière fois."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 5400401
L16_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L16_1.m_Pos = "R"
L16_1.m_Talk_KOREA = "가만뒀다간 경기 직전까지 시뮬레이터에 처박혀 있어야 할 걸."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "ほっといたら、試合直前までシミュレーターに引きこもり確定だよ。"
L16_1.m_Talk_ENG = "Leave her like that, and we'll be stuck in the simulator until the match."
L16_1.m_Talk_TWN = "如果放著她不管，比賽之前她會一直待在模擬器裡。"
L16_1.m_Talk_THA = "ปล่อยเธอไว้อย่างนั้นแล้วเราจะติดอยู่ในเครื่องจำลองซ้อมไปจนกว่าจะถึงการแข่งขัน"
L16_1.m_Talk_VTN = "Cứ để nhóc ấy như vậy thì cả lũ sẽ mắc kẹt trong trình giả lập cho đến trận đấu mất."
L16_1.m_Talk_SCN = "如果放着她不管，比赛之前她会一直待在模拟器里。"
L16_1.m_Talk_DEU = "Wenn wir nichts unternehmen würden, wären wir bis kurz vor dem Spiel im Simulator eingesperrt."
L16_1.m_Talk_FRA = "Si on la laisse tranquille, on va devoir resteer dans le simulateur jusqu'au match."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 5400401
L17_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_SERIOUS"
L17_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L17_1.m_Pos = "R"
L17_1.m_Talk_KOREA = "그러니 곯아떨어진 채로 데리고 나가서 기정 사실로 만들어 버린다!"
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "だから、寝てる間に連れ出して、既成事実にしちゃうのさ！"
L17_1.m_Talk_ENG = "So, we'll take her outside while she's asleep!"
L17_1.m_Talk_TWN = "所以趁她睡著的狀態下帶出去，製造既定事實！"
L17_1.m_Talk_THA = "เราจะพาเธอออกไปข้างนอกในขณะที่เธอหลับ!"
L17_1.m_Talk_VTN = "Nên chúng tôi sẽ đưa nhóc ấy ra ngoài khi đang ngủ!"
L17_1.m_Talk_SCN = "所以在她睡着的状态下带出去，制造既成事实！"
L17_1.m_Talk_DEU = "Also bringen wir sie nach draußen, während sie schläft!"
L17_1.m_Talk_FRA = "Alors on l'emmène dehors pendant qu'elle dort !"
L18_1 = {}
L18_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 5400401
L18_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L18_1.m_bWaitClick = true
