L18_1.m_Pos = "L"
L18_1.m_Talk_KOREA = "다시 들어도 흠잡을 데 없는 완벽한 작전이에요!"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "まさに、抜け目のない完璧な作戦です！"
L18_1.m_Talk_ENG = "It's a perfect plan, no flaws whatsoever!"
L18_1.m_Talk_TWN = "再聽一遍也是沒有分毫瑕疵的完美作戰計畫！"
L18_1.m_Talk_THA = "เป็นแผนการที่ดีเลย"
L18_1.m_Talk_VTN = "Đó là một kế hoạch hoàn hảo, không có sai sót nào!"
L18_1.m_Talk_SCN = "再听一遍也是没有分毫瑕疵的完美作战计划！"
L18_1.m_Talk_DEU = "Es ist ein perfekter Plan, ohne irgendwelche Schwachstellen!"
L18_1.m_Talk_FRA = "C'est vraiment le plan parfait !"
