L21_1.m_Talk_KOREA = "(말해도 안 통하겠군.)"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "(話しても無駄だろうな。)"
L21_1.m_Talk_ENG = "(Talking to them is pointless.)"
L21_1.m_Talk_TWN = "（好像溝通無效。）"
L21_1.m_Talk_THA = "(การพูดคุยกับพวกเขาไม่มีจุดหมาย)"
L21_1.m_Talk_VTN = "(Chắc nói nữa cũng không thông.)"
