L21_1.m_Talk_DEU = "(Es bringt nichts, mit ihnen zu sprechen.)"
L21_1.m_Talk_FRA = "(Leur parler est inutile.)"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 5400401
L22_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
