L22_1.m_ActionStrKey = "MARK3"
L22_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "미리 경고하는데, 사이코 꼬맹이는 저혈압이야."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "警告しておくけど、サイコガキは低血圧なんだ。"
L22_1.m_Talk_ENG = "I'm warning you, psycho kid gets cranky when she wakes up."
L22_1.m_Talk_TWN = "我先警告你們，這小瘋子可是有起床氣的。"
L22_1.m_Talk_THA = "ฉันเตือนคุณแล้ว เด็กโรคจิตจะบ้าๆ บอๆ เมื่อตื่นขึ้น"
L22_1.m_Talk_VTN = "Tôi đang cảnh báo tất cả, con bé điên sẽ cáu kỉnh khi tỉnh dậy đấy."
L22_1.m_Talk_SCN = "我得先警告你们啊，这个疯丫头可是有起床气的。"
L22_1.m_Talk_DEU = "Ich warne dich schon mal vorab, das Psycho-Gör wird schlecht gelaunt sein, wenn es aufwacht."
L22_1.m_Talk_FRA = "Je vous préviens, la psycho est pas d'humeur quand elle se réveille."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "CHARADE_ACT4_INTERLUDE1@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 5400401
L23_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "밖으로 옮기다가 잠에서 깨면 깨물 수도 있으니까 조심하라구."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "外に運ぶ途中で目覚めたら噛まれる可能性があるから、気をつけろよ。"
L23_1.m_Talk_ENG = "She might bite you if she wakes up on the way out."
L23_1.m_Talk_TWN = "要是在搬運過程中吵醒她的話，可是會咬人的，大家要小心。"
L23_1.m_Talk_THA = "เธออาจจะกัดคุณถ้าเธอตื่นขึ้นระหว่างทาง"
L23_1.m_Talk_VTN = "Nếu nó lỡ tỉnh lúc bị bế ra ngoài thì sẽ cắn người đấy, cẩn thận."
L23_1.m_Talk_SCN = "要是在搬运过程中吵醒她的话，可是会咬人的，大家要小心。"
L23_1.m_Talk_DEU = "Sie könnte dich sogar beißen, wenn sie auf dem Weg nach draußen aufwacht."
L23_1.m_Talk_FRA = "Elle pourrait se mettre à vous mordre si elle se réveille en chemin."
L24_1 = {}
