L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "それじゃあ、行くぞ！　全員、突撃！！"
L24_1.m_Talk_ENG = "All right, here we go! All members, charge!"
L24_1.m_Talk_TWN = "那就動手囉！全員突擊！！"
L24_1.m_Talk_THA = "เอาล่ะ ไปกันเลย! สมาชิกทุกท่าน!"
L24_1.m_Talk_VTN = "Được rồi đi thôi! Tất cả các thành viên, xông lên!"
L24_1.m_Talk_SCN = "都没问题了吧！那就全员突击！！"
L24_1.m_Talk_DEU = "Alles klar! Alle Mitglieder, los geht‘s!!"
L24_1.m_Talk_FRA = "Bon, c'est parti ! On y va !"
