L41_1 = "아, 일어났구나. 펠리세트."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あ、起きたんだね。フェリセット。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Oh, you're awake, Félicette."
L40_1.m_Talk_ENG = L41_1
L41_1 = "你醒啦，費莉塞特。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "โอ้ เธอตื่นแล้วเฟลิเซต"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ồ, tỉnh rồi à Félicette."
L40_1.m_Talk_VTN = L41_1
L41_1 = "啊，你醒了啊，菲利塞特。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Oh, du bist aufgewacht. Felicette."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Oh, tu es réveillée, Felicette."
