L42_1 = "졸리면 더 쉬어도 돼."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "眠かったらもっと休んでてもいいよ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Rest more if you're tired."
L41_1.m_Talk_ENG = L42_1
L42_1 = "睏的話就再睡一會。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "พักผ่อนให้มากๆนะ หากเธอรู้สึกเหนื่อย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Cứ nghỉ ngơi nhiều hơn nếu mệt."
L41_1.m_Talk_VTN = L42_1
L42_1 = "困的话就再睡一会。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ruh dich noch ein wenig aus, wenn du müde bist."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Tu devrais te reposer un peu plus si tu es fatiguée."
