L44_1 = "FELICETTE_CANARY_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "여긴 어디에요? 분명 전력 분석하다 소파에서 잠들었는데……?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ここはどこですか？　確か戦力分析をしていて、ソファで寝落ちしたかと……？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Where are we? I thought I fell asleep on the sofa while analyzing our forces..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "這裡是什麼地方？我明明記得我在分析戰力，然後在沙發上睡著了……？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เราอยู่ที่ไหน ฉันคิดว่าฉันหลับไปบนโซฟาในขณะที่วิเคราะห์กองกำลังของเรา..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Đây là đâu? Tôi tưởng tôi ngủ quên trên ghế sofa lúc phân tích chiến lực mà.."
L43_1.m_Talk_VTN = L44_1
L44_1 = "这里是什么地方？我明明记得自己在分析战力，然后在沙发上睡着了……？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wo sind wir? Ich dachte, ich wäre auf dem Sofa eingeschlafen, während ich unsere Leistung analysiert habe ..."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Où est-ce qu'on est ? Je suis pourtant sure de m'être endormie sur le canapé en analysant notre stratégie..."
L43_1.m_Talk_FRA = L44_1
