L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_IDLE"
L47_1 = "STAFF_CANARY_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "R"
L47_1 = "번화가에 있는 음식점. 노엘이 아침 식사가 맛있다고 추천해 줬어."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "繁華街にある食堂よ。ノエルがここの朝食がおいしいってすすめてくれたの。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "We're in a restaurant downtown. Noelle recommended the place for their breakfast menu."
L46_1.m_Talk_ENG = L47_1
L47_1 = "這裡是美食街的餐廳，洛艾兒說這裡的早餐很好吃，推薦大家過來吃。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เราอยู่ในร้านอาหารใจกลางเมือง โนเอลแนะนำสถานสำหรับเมนูอาหารเช้าของพวกเรา"
L46_1.m_Talk_THA = L47_1
L47_1 = "Chúng ta đang ở trong một nhà hàng ở trung tâm thành phố. Noelle nói bữa sáng ở đây ngon lắm nên bảo mọi người tới đây."
L46_1.m_Talk_VTN = L47_1
L47_1 = "这里是商业街上的餐厅。诺艾尔说这里的早餐很好吃，推荐大家过来的。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Wir sind in einem Restaurant in der Innenstadt. Noelle hat es wegen des leckeren Frühstückmenüs empfohlen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "On est dans un restaurant du centre-ville. Noelle recommande leur petit déjeuner, il parait qu'il est délicieux."
L46_1.m_Talk_FRA = L47_1
