L49_1 = "UNIT_HATE"
L48_1.m_Face = L49_1
L49_1 = "FELICETTE_CANARY_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "외식은 나중에 하자고 했잖아요. 하여튼 마음대로…."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "外食は後でって言ったじゃないですか。まったく、勝手に……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I told you we should eat out later. Tsk, so stubborn..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我不是說以後再出去吃飯？哼，真是任性……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันบอกพวกเธอแล้วว่าเราควรจะออกไปกินข้าวครั้งหน้า ชิ ดื้อจัง..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi đã bảo là chúng ta nên ăn ngoài sau mà. Chậc, cứng đầu thế nhỉ..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "我不是说了以后再出去吃饭？哼，真是任性……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich hatte doch gesagt, dass wir später essen gehen sollen. Ihr macht einfach immer, was ihr wollt ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je vous ai dit qu'on devrait aller au restaurant plus tard. Vous êtes si têtues..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
