L50_1 = "셋 다 얼굴이 왜 그래요? 누가 할퀴었어요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "三人とも、顔はどうしたの？　誰かにひっかかれでもした？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Wait, what's wrong with your faces? Did something claw you?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "你們三個的臉怎麼回事？被誰抓的？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เดี๋ยวก่อน เกิดอะไรขึ้นกับใบหน้าของเธอ? มีอะไรติดเล็บเธอหรือเปล่า?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Ơ mặt mấy người làm sao thế? Ai cào vậy?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "你们三个的脸怎么了？谁挠你们了？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Was ist mit euren Gesichtern passiert? Hat euch jemand gekratzt?"
L49_1.m_Talk_DEU = L50_1
