L3_1 = "지옥에서 올라온 미친 고양이를 잡으려다가 입은 부상이야."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "地獄から這い上がってきたネコを捕まえようとして怪我したんだよ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I was trying to catch this crazy devil cat."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我們是在捕捉從地獄跑出來的瘋狂貓咪時受傷的。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฉันพยายามจะจับแมวปีศาจบ้าๆตัวนี้"
L2_1.m_Talk_THA = L3_1
L3_1 = "Do tôi cố bắt con mèo quỷ điên khùng này."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我们是为了抓捕从地狱里跑出来的神经质小猫才受伤的。"
L2_1.m_Talk_SCN = L3_1
