L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "자고 있는 널 데려 오느라 그랬대."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "寝てるあなたを連れ出そうとしてこうなったんだって。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "They had trouble trying to move you here while you were asleep."
L7_1.m_Talk_ENG = L8_1
L8_1 = "他們把你搬出來時弄的。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "พวกเขามีปัญหาในการพยายามพาเธอมาที่นี่ในขณะที่เธอหลับ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Là vì mang nhóc tới đây trong khi nhóc ngủ đấy."
L7_1.m_Talk_VTN = L8_1
L8_1 = "为了把睡着的你带出来弄的。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sie hatten Probleme, dich hierher zu bringen, während du geschlafen hast."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Ils ont eu du mal à te déplacer pendant que tu dormais, on va dire."
