L10_1 = "FELICETTE_CANARY_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "상관없죠. 훈련은 아침을 먹고 나서 하면 되니까요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "いいでしょう。訓練は朝食を食べてからすればいいですから。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I guess it's fine. We'll train after eating breakfast."
L9_1.m_Talk_ENG = L10_1
L10_1 = "無所謂，吃完早飯再訓練吧。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันคิดว่ามันสบายดี เราจะฝึกซ้อมหลังจากรับประทานอาหารเช้า"
L9_1.m_Talk_THA = L10_1
L10_1 = "Tôi đoán nó ổn thôi. Chúng ta sẽ tập luyện sau khi ăn sáng."
L9_1.m_Talk_VTN = L10_1
L10_1 = "无所谓啊，吃完早饭再训练就行了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich denke, es macht keinen großen Unterschied. Wir können auch noch nach dem Frühstück trainieren."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Bon, ça devrait le faire. On ira s'entraîner après avoir mangé."
L9_1.m_Talk_FRA = L10_1
