L12_1 = "MARK4"
L11_1.m_ActionStrKey = L12_1
L12_1 = "부상자들에게 훈련을 시킬 셈인가?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "怪我人に訓練をさせるつもりか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You want them to train when they're all injured?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "你是打算讓傷患們訓練嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "คุณต้องการให้พวกเขาฝึกซ้อมตอนที่พวกเขาได้รับบาดเจ็บหรอ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cô muốn họ tập khi tất cả đều bị thương sao?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "哈哈，你是打算让伤员们训练嘛？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Du möchtest, dass sie trainieren, wenn sie alle verletzt sind?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Tu veux qu'elles s'entraînent alors qu'elles sont toutes blessées ?"
