L16_1 = "L_M_I"
L15_1.m_Pos = L16_1
L16_1 = "미나 선배! 펠리세트에게 물린 손이 갑자기 움직이지 않아요!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "ミナ先輩！　フェリセットに噛まれた手が、急に動きません！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Mina! The hand Félicette bit, I can't move it! It's turning cold!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "米娜前輩！我被費莉塞特咬傷的手突然動彈不得！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "มีนา! เฟลิเซตกัดมือ ฉันขยับไม่ได้! เริ่มหนาวแล้ว!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Mina! Tay bị Félicette cắn em không cử động được! Nó đang lạnh!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "米娜前辈！我被菲利塞特咬伤的手突然不能动了！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Mina! Ich kann die Hand, die Felicette gebissen hat, plötzlich nicht mehr bewegen!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mina ! Ma main ne bouge plus !"
L15_1.m_Talk_FRA = L16_1
