L17_1 = "m_Crash"
L16_1[L17_1] = 15
L17_1 = "오늘 하루만 푹 쉬면 나을 것 같은데 어떡하죠?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "今日一日だけゆっくり休めば治りそうですけど、どうしましょう？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Maaaaybe a good day's rest will cure it! What do I do?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "我覺得今天好好休息一天就能痊癒，怎麼辦呢？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "อาจจะต้องพักผ่อนและรักษามันก่อน!  "
L16_1.m_Talk_THA = L17_1
L17_1 = "Có lẽee một ngày nghỉ mới khỏi được! Em làm gì bây giờ?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "我感觉今天好好休息一天就能痊愈，怎么办呢？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich denke, dass es besser wäre, wenn ich heute ausnahmsweise eine Pause einlegen würde."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mais peut-être qu'une journée de repos pourrait remettre tout ça en place..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "CHARADE_ACT4_INTERLUDE1@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5400401
L17_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L17_1.m_bWaitClick = true
