L18_1 = "m_Crash"
L17_1[L18_1] = 20
L18_1 = "그, 그래. 이 상태로 훈련 받긴 힘들겠네."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "そ、そう。このまま訓練するのは難しそうだね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "R-right. You don't look like you're fit to train today."
L17_1.m_Talk_ENG = L18_1
L18_1 = "嗯，也是，這種狀態進行訓練是有點困難。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ช -ใช่ เธอดูไม่เหมาะที่จะฝึกซ้อมในวันนี้"
L17_1.m_Talk_THA = L18_1
L18_1 = "P-phải rồi. Cô có vẻ không đủ khỏe để tập hôm nay."
L17_1.m_Talk_VTN = L18_1
L18_1 = "当、当然。这个状态进行训练是有点困难。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "O-okay. Du siehst nicht so aus, als wärst du fit für das heutige Training."
L17_1.m_Talk_DEU = L18_1
L18_1 = "C-C'est vrai ça. Tu ferais mieux de ne pas t'entraîner aujourd'hui."
