L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5400401
L20_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
