L20_1.m_Face = "UNIT_LAUGH"
L20_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L21_1 = "L_M_I"
L20_1.m_Pos = L21_1
L21_1 = "스키너, 인터뷰할 때 얼굴에 난 상처는 뭐라고 설명할까?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "スキナー、インタビューの時に私の顔にできた傷はなんて説明しよっか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Skinner, what should I say when they ask about the scar on my face during the interview?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "史金納，採訪時我要怎麼解釋臉上的傷口？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "สกินเนอร์ ฉันควรพูดอะไรดีหากพวกเขาถามเกี่ยวกับแผลเป็นบนใบหน้าของฉันตอนสัมภาษณ์"
L20_1.m_Talk_THA = L21_1
L21_1 = "Skinner, tôi nên nói gì khi họ phỏng vấn vết sẹo trên mặt tôi?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "斯金纳，采访时我要怎么解释脸上的伤口啊？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Skinner, was soll ich sagen, wenn sie mich während des Interviews nach den Kratzern in meinem Gesicht fragen?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Skinner, qu'est-ce que je devrais dire quand ils vont me demander pour la cicatrice sur mon visage pendant l'interview ?"
L20_1.m_Talk_FRA = L21_1
