L22_1 = "CHARADE_ACT4_INTERLUDE1@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5400401
L21_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L21_1.m_Pos = "L"
L22_1 = "까딱 잘못했다가 스폰서 제의도 못 받는 거 아냐?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "下手したら、スポンサーの提案を外されるんじゃない？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "What if our sponsors decide to cut us off?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "搞不好連贊助商的合約都拿不到吧？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "จะเกิดอะไรขึ้นหากผู้สนับสนุนของเราตัดสินใจที่จะตัดเราออก?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nếu nhà tài trợ quyết định cắt hợp đồng thì phải làm sao?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "搞不好连赞助商的提案都拿不到吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Was ist, wenn wir unsere Sponsoren verlieren?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Et si nos sponsors ne nous payaient plus à cause de ça ?"
L21_1.m_Talk_FRA = L22_1
