L23_1 = "STAFF_CANARY_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "R"
L23_1 = "그럼 곤란하지. 본선에 나가려면 최소한 헬기 한 대는 필요할 텐데."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "それじゃ困るよ。本戦に出るためには、少なくともヘリ1機は必要なのに。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Oh, that won't do. We'll need at least one chopper to get to the elimination round."
L22_1.m_Talk_ENG = L23_1
L23_1 = "那可不行。決賽裡想贏，隊裡至少還需要一架直升機。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "โอ้ นั่นจะไม่มีการไล่ออก เราต้องการชอปเปอร์อย่างน้อยหนึ่งตัวเพื่อเข้าสู่รอบ"
L22_1.m_Talk_THA = L23_1
L23_1 = "A, không được. Muốn tham gia chung kết thì ít nhất phải có 1 chiếc trực thăng."
L22_1.m_Talk_VTN = L23_1
L23_1 = "那可不行。淘汰赛里想赢，队里至少还需要一架直升机。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Oh, das geht doch nicht. Wir brauchen mindestens einen Hubschrauber, um es ins Finale zu schaffen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ça serait embêtant. Il nous faut au moins un hélicoptère pour participer aux phases éliminatoires."
L22_1.m_Talk_FRA = L23_1
