L31_1 = "m_Crash"
L30_1[L31_1] = 20
L31_1 = "마침 좋은 기회네요! 샤레이드에 올 때 혼신의 힘을 다해 짜 둔 관광 코스가 있거든요!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ちょうどよかったです！　シャレードに来る時、渾身の力を込めて組んだ観光コースがあるんですよ！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "This is great news! I have a thoroughly planned tour that I made on my way to Charade!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "那正是個好機會！來查雷德的時候，我絞盡腦汁計畫了一個完美的旅遊路線！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "นี่เป็นข่าวดี! ฉันได้วางแผนทัวร์ไว้อย่างละเอียดแล้ว ตอนที่ไปเมืองชาเรด!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Một tin tuyệt vời! Tôi đã lên kế hoạch tham quan trên đường đến Charade đấy!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "那正是个好机会！来查雷德的时候，我绞尽脑汁制定了一个完美的旅游路线！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das sind doch endlich mal gute Neuigkeiten! Ich habe eine Tour, die ich auf dem Weg nach Charade bis ins kleinste Detail durchgeplant habe!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mais c'est une superbe nouvelle ! J'ai justement préparé un tour de Charade en venant ici ! Je me suis vraiment donné du mal !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "CHARADE_ACT4_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
