L33_1 = "헤헷. 첫 상여금으로 산 가이드 북인데 그냥 두긴 아깝잖아요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "へへっ。初めてのボーナスで買ったガイドブックなのに、見ないなんてもったいないじゃないですか。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "He he. It's a travel guide I bought with my first bonus salary. I didn't want it to go to waste."
L32_1.m_Talk_ENG = L33_1
L33_1 = "嘿嘿，這可是我用第一筆獎金買的旅遊指南，就那麼放著多可惜。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฮิฮิ มันเป็นทัวร์เที่ยวที่ฉันซื้อด้วยเงินเดือนโบนัสครั้งแรกของฉัน ฉันไม่อยากให้มันเสียเปล่า"
L32_1.m_Talk_THA = L33_1
L33_1 = "He he. Đó là cẩm nang du lịch mà tôi đã mua bằng tiền lương đầu tiên của mình. Tôi không muốn lãng phí nó."
L32_1.m_Talk_VTN = L33_1
L33_1 = "嘿嘿，这可是我用第一笔奖金买的旅游指南，就那么放着多可惜啊。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hehe. Es ist ein Reiseführer, den ich mit meinem ersten Bonus gekauft habe. Es wäre eine Verschwendung, ihn nicht zu nutzen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Hé hé. Regardez. C'est un guide de voyage que j'ai acheté avec mon premier salaire. Il faut bien l'utiliser un jour ou l'autre !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
