L34_1 = "오늘 하루는 저 노엘에게 맡겨 주세요!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "今日一日は私、ノエルに任せてください！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Leave everything up to Noelle for today!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "今天一天就交給我洛艾兒吧！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ปล่อยทุกอย่างให้โนเอลคนนี้จัดการเองวันนี้!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Hãy để mọi thứ cho Noelle lo!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "今天一天就交给我诺艾尔吧！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Überlassen Sie heute ausnahmsweise mal alles mir, Noelle!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Laissez-moi m'occuper de tout aujourd'hui !"
L33_1.m_Talk_FRA = L34_1
