L36_1.m_Face = "UNIT_SERIOUS"
L37_1 = "FELICETTE_CANARY_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "L"
L37_1 = "훈련을 쉰다고 했지, 놀자고 한 적은 없어요!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "訓練を休むだけで、遊びに行こうと言ったわけではないわ！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I said we're skipping training, not hanging out!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "我是說不用訓練，可沒說要出去玩！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฉันบอกว่าเราซ้อม ไม่ได้ออกไปเที่ยวไหน!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tôi đã nói là chúng ta bỏ tập, không đi chơi!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "我说的是不用训练了，我可没说过出去玩啊！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich sagte zwar, wir überspringen das Training, aber das heißt nicht, dass wir herumalbern können!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "J'ai dis qu'on ne s'entraînait pas. Pas qu'on allait traîner un peu partout."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "CHARADE_ACT4_INTERLUDE1@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5400401
L37_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L37_1.m_Pos = "R"
L38_1 = "너도 좋으면서 왜 그래. 사람도 기계도 일만 하면 병드는 거야."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あんたも嬉しいくせに。人も機械も、仕事ばっかりしてると病むよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Come on, don't tell me you don't like the idea. All work and no play makes everyone dull."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你明明就很開心，幹嘛口是心非。人也好機器也好，只顧著工作的話會生病的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อย่าบอกนะว่าพวกเธอไม่ชอบไอเดียนี้ การทำงานหนักหากไม่ปลีกตัวไปเที่ยวบ้าง มันจะทำให้ทุกคนเบื่อ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Thôi nào, đừng nói với nhóc không thích đi chơi nhé. Chỉ có làm việc mà không chơi thì sinh bệnh mất."
L37_1.m_Talk_VTN = L38_1
L38_1 = "你明明也喜欢的，干嘛口是心非的样子。人也好机器也好，只顾着工作的话会生病的。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Komm schon, sag mir nicht, dass dir die Idee nicht gefällt. Sowohl Menschen als auch Maschinen werden krank, wenn sie nur arbeiten."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Allez, fais pas genre que ça te ferait pas plaisir ! Tu vas devenir une vraie aigrie si tu t'amuses jamais."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
