L40_1 = "걱정 마세요! 코스 중에 건틀렛 박물관도 넣어 뒀거든요!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "心配しないでください！　コースの中には、ガントレット博物館もありますから！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Don't worry! I've included the Gauntlet Museum in our tour!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "別擔心！我還有在旅遊路線中加入聖鎧博物館喔！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ไม่ต้องกังวล! ฉันได้รวมพิพิธภัณฑ์กอนต์เล็ตไว้ในทัวร์ของเราแล้ว!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đừng lo! Tôi đã bao gồm Bảo tàng Gauntlet trong chuyến đi rồi."
L39_1.m_Talk_VTN = L40_1
L40_1 = "别担心！我在旅游路线中还加入了圣铠博物馆！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Keine Sorge! Ich habe das Fehde-Museum in unsere Tour mitaufgenommen!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Ne t'inquiète pas ! Le musée de la compétition est inclus dans notre tour !"
L39_1.m_Talk_FRA = L40_1
