L41_1.m_Face = "UNIT_IDLE"
L41_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "네. 펠리세트라면 구경하고 싶어할 것 같아서요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "はい。フェリセットなら観覧したがるだろうと思ったんで。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Yes. I thought you would want to check it out."
L41_1.m_Talk_ENG = L42_1
L42_1 = "是的，因為我覺得費莉塞特應該會想參觀。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ใช่ ฉันคิดว่าพวกเธอต้องอยากไป "
L41_1.m_Talk_THA = L42_1
L42_1 = "Đúng. Tôi nghĩ cô sẽ muốn thử ngó nó."
L41_1.m_Talk_VTN = L42_1
L42_1 = "是的，因为我觉得菲利塞特应该会想参观。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ja. Ich dachte, du würdest es dir gerne mal ansehen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Eh oui. Je me suis dit que tu aimerais y jeter un oeil..."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "CHARADE_ACT4_INTERLUDE1@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5400401
L42_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L42_1.m_bWaitClick = true
