L43_1 = "FELICETTE_CANARY_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "……구경이 아니라 견학이겠죠."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……観覧じゃなくて、見学でしょう。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "...It would be a field trip, not \"checking it out.\""
L42_1.m_Talk_ENG = L43_1
L43_1 = "……不是參觀，是見習。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "...ดีนะนั่นเป็นการไปทัศนศึกษา ไม่แค่นั้นยังได้ไป... \"สอดส่อง\""
L42_1.m_Talk_THA = L43_1
L43_1 = "...Đó sẽ là một chuyến đi thực địa, chứ không phải \"ngó nó.\""
L42_1.m_Talk_VTN = L43_1
L43_1 = "……不是参观，是“分析”。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "... Es wäre also eine Exkursion, kein „Sightseeing“."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Alors ce n'est pas du tourisme... On va faire une sorte... de sortie scolaire."
L42_1.m_Talk_FRA = L43_1
