L45_1.m_Pos = "R_M_I"
L46_1 = "이 응큼한 꼬맹이. 입꼬리 올라간 것 좀 봐."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "この悪賢いおこちゃまめ。口角が上がってる。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "You sly kid. Look at you, all smiling."
L45_1.m_Talk_ENG = L46_1
L46_1 = "เจ้าเด็กเจ้าเล่ห์ ดูเธอยิ้มเข้าสิ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Con bé này. Nhìn mặt đang cười đó."
L45_1.m_Talk_VTN = L46_1
L46_1 = "真是厚脸皮的小鬼欸，嘴角都翘起来了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Du listiges Gör. Schau sich mal einer an, wie sich deine Mundwinkel nach oben bewegen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Regardez-la. Toute souriante."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "CHARADE_ACT4_INTERLUDE1@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5400401
L46_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L46_1.m_Pos = "R"
L47_1 = "말은 그렇게 해도 표정은 솔직하잖아."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "言葉に反して、顔は素直だな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It's written all over your face."
L46_1.m_Talk_ENG = L47_1
L47_1 = "雖然嘴硬，不過表情卻很誠實嘛。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "มันดูออกทั่วใบหน้าของเธอเลยรู้ไหม"
L46_1.m_Talk_THA = L47_1
L47_1 = "Nó hiện lên hết trên mặt rồi kìa."
L46_1.m_Talk_VTN = L47_1
L47_1 = "虽然嘴硬，不过表情却很诚实嘛。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Auch wenn du desinteressiert tust, steht dir die Begeisterung ins Gesicht geschrieben."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ça se voit que tu es trop contente, gamine."
L46_1.m_Talk_FRA = L47_1
