L51_1 = "그럼 우선 주문부터 할까? 많이 돌아다니려면 배가 든든해야지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それじゃあ、まずは注文からしようか？　たくさん歩き回るためには、お腹いっぱい食べないと。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Should we order first? We need a good meal to keep up with that hectic schedule."
L50_1.m_Talk_ENG = L51_1
L51_1 = "那先點餐吧？要想多逛一會兒，得先吃飽才行。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "พวกเราสั่งอะไรก่อนไหม? เราต้องการอาหารที่ดีเพื่อให้ทันกับตารางงานที่วุ่นวายนั้น"
L50_1.m_Talk_THA = L51_1
L51_1 = "Chúng ta có nên gọi đồ trước không? Phải ăn no mới theo kịp lịch trình bận rộn đó đấy."
L50_1.m_Talk_VTN = L51_1
L51_1 = "那先点餐吧？要想多逛一会儿，得先吃饱才行。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Sollen wir erst mal was bestellen? Wer sich viel bewegen möchte, muss sich vorher mit leckeren Essen stärken."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Et si on commandait, maintenant ? Il va nous falloir un bon repas pour tenir notre programme."
L50_1.m_Talk_FRA = L51_1
