L12_1 = "管理局が行ってる絶滅危惧種の復元過程も、はっきりと観覧可能！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You can even watch the endangered species recovery program, managed by the Administration!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "可以現場觀看管理局進行的瀕危生物復育計畫！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "พวกคุณสามารถไปดูการอนุรักษ์สัตว์ใกล้สูญพันธุ์ที่บริหารโดยองค์การบริหารโลก!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cô còn có thể xem chương trình phục hồi các loài có nguy cơ tuyệt chủng do Cục Quản Lý quản lý!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "可以现场观看管理局进行的濒危生物复苏计划！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Man kann sogar den von der Administration durchgeführten Wiederherstellungsprozess für gefährdete Arten hautnah verfolgen!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "On peut y voir des espèces rares grâce au programme de rétablissement des animaux en voie d'extinction ! Tout ça est géré par l'Administration."
L11_1.m_Talk_FRA = L12_1
