L16_1 = "손님이 먹이로 준 정어리에 문제가 있어서 당분간 쉰다는데?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "お客さんがエサとしてあげたイワシに問題があって、しばらく休むらしいよ？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It says that they're closed due to some problems with the fish the visitors gave them."
L15_1.m_Talk_ENG = L16_1
L16_1 = "說是因為客人們餵食的沙丁魚有問題，所以暫時休息？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "พวกเขาบอกว่ากำลังปิดปรับปรุงอยู่นิ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Hình như họ đã đóng cửa vì khách đút cho chúng ăn mấy con cá có vấn đề."
L15_1.m_Talk_VTN = L16_1
L16_1 = "说是因为客人们投喂的沙丁鱼有问题，所以暂时休息？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Hier steht, dass es ein Problem mit den Sardinen gab, die die Besucher ihnen gegeben haben, weshalb ihr Gehege fürs Erste geschlossen ist."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Euh... Ils disent que c'est fermé. Il y a eu des problèmes à cause d'une sardine qu'un visiteur a donné aux pingouins."
