L31_1.m_Talk_JPN = L32_1
L32_1 = "This is where they restored the Old City during war times."
L31_1.m_Talk_ENG = L32_1
L32_1 = "聽說這裡是在舊城區的基礎上重現戰爭當時的原貌。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "นี่คือช่วงที่พวกเขากำลังบูรณะเมืองเก่าในช่วงหลังสงคราม"
L31_1.m_Talk_THA = L32_1
L32_1 = "Đây là nơi họ khôi phục Thành phố cổ trong thời chiến."
L31_1.m_Talk_VTN = L32_1
L32_1 = "听说这里在旧城区的基础上重现了战争当时的原貌。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hier wurde die Altstadt in den Zustand der Kriegszeit zurückversetzt."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ils ont fidèlement reconstitué la vieille ville, telle qu'elle était durant la guerre."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "CHARADE_ACT4_INTERLUDE1@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 5400401
L32_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_LAUGH"
L32_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "실감 나는 디오라마를 감상하면서 전쟁 전 이 지역 특산물로 만든 요리도 맛볼 수 있어요!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "リアリティ溢れるジオラマを鑑賞しながら、戦前のこの地域の特産物で作った料理も味わえますよ！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "We can taste the food made from the region's specialties from before the war while enjoying the realistic diorama!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "可以一邊欣賞生動的微型立體景觀，一邊品嚐戰爭爆發之前該地區的特產美食！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เราสามารถลองชิมอาหารดั้งเดิมตั้งแต่สมัยก่อนมีสงครามได้ในขณะที่เดินดูภาพเมืองจำลอง!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Chúng ta có thể vừa thưởng thức tranh tầm sâu vừa thưởng thức các món ăn được chế biến từ đặc sản nơi đó từ trước chiến tranh."
L32_1.m_Talk_VTN = L33_1
L33_1 = "可以一边欣赏生动的微型立体景观，一边品尝战争爆发之前该地区的特产美食！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Während man das realistische Diorama betrachtet, kann man auch Gerichte probieren, die vor dem Krieg mit lokalen Spezialitäten zubereitet wurden!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "On va pouvoir déguster des plats préparés avec des produits locaux d'avant-guerre tout en admirant un diorama réaliste !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "CHARADE_ACT4_INTERLUDE1@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5400401
