L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "샤레이드의 화려함과 동떨어진 이색적인 분위기! 오늘 점심은 여기서 먹어요!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "派手なシャレードとはかけ離れた異色の雰囲気！　今日のランチはここで食べましょう！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "A refreshing scenery, away from Charade's flashy lights and signposts! Let's have lunch here!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "這是與查雷德的華麗相去甚遠的特色氛圍！今天的午餐就在這裡吃吧！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ทิวทัศน์ที่สดชื่น ชาเรดที่ห่างไกลจากแสงสีไฟและป้ายบอกทาง! มาทานมื้อเที่ยงกันที่นี่เลย!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Một khung cảnh tươi mới, tránh xa ánh đèn hào nhoáng và biển chỉ dẫn của Charade! Trưa nay ăn ở đây nhé!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "这是与查雷德的华丽相去甚远的特色氛围！今天的午餐就在这里吃吧！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Eine einzigartige Atmosphäre fernab der Pracht von Charade! Lassen Sie uns hier zu Mittag essen!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Quel paysage unique ! Ça change des lumières de Charade ! On devrait manger ici !"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
