L37_1 = "CHARADE_ACT4_INTERLUDE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5400401
L36_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "MINA_FENRIR_CHIEF_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "R"
L37_1 = "저기 있는 경고문은 무시해도 되는 거야?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "あそこにある警告文は無視していいの？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Shouldn't we acknowledge that warning sign over there?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "現在是要無視那邊的警告標示嗎？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "นี่เราไม่แคร์สัญญาณเตือนตรงนั้นหรอ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Chúng ta không nên bỏ qua cảnh báo đằng kia nhỉ?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "那边的警告要无视吗？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wollen wir die Warnung dort drüben einfach ignorieren?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vous êtes sûres qu'on peut ignorer ce panneau d'avertissement ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "CHARADE_ACT4_INTERLUDE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5400401
L37_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "STAFF_CANARY_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "L"
L38_1 = "어라, 공사 중이라네. 조용한 분위기는 아니겠는데."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あれ、工事中だって。静かな雰囲気じゃなさそうだけど。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Huh? It says that it's under maintenance. Doesn't sound so refreshing to me."
L37_1.m_Talk_ENG = L38_1
L38_1 = "哎呀，正在施工呢，那應該會很吵吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "หืม? มันบอกว่าอยู่ระหว่างการบำรุงรักษาอีกละ เห็นแบบนี้ฉันไม่ค่อยปลื้มเลย "
L37_1.m_Talk_THA = L38_1
L38_1 = "Hả? Nó bảo là đang bảo trì. Có vẻ không yên tĩnh lắm đâu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "哎呀，正在施工啊，环境应该不是很安静吧。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Huch? Hier finden gerade Umbauarbeiten statt. Das dürfte recht laut werden."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Hum ? C'est en travaux. Adieu la pause tranquille."
L37_1.m_Talk_FRA = L38_1
