L43_1 = 2
L44_1 = 0.15
L42_1[1] = L43_1
L42_1[2] = L44_1
L40_1[L41_1] = L42_1
L41_1 = "앗, 그래도 덕분에 실제 전쟁터 같은 현장감이 느껴지지 않을까요!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あっ、でもおかげで、実際の戦場みたいな臨場感が感じられるんじゃないでしょうか！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Ah, but then, maybe it'll make the atmosphere feel more realistic, just like the war!"
L40_1.m_Talk_ENG = L41_1
L41_1 = "不過這樣我們才能感受到戰場般的臨場感吧！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "อืม แต่บางทีมันอาจจะทำให้บรรยากาศสมจริงมากขึ้น เหมือนกับอยู่ในสงคราม!"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ah, nhưng thế thì nó sẽ làm không khí trở nên chân thực hơn, giống như chiến tranh ấy!"
L40_1.m_Talk_VTN = L41_1
L41_1 = "啊，不过这样我们才正好能感受到战场般的现场感吧！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ah, aber vielleicht wirkt die Atmosphäre dadurch noch realistischer, genau wie im Krieg!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "C'est pas grave ! L'ambiance sera encore plus réaliste. Une véritable ambiance de guerre !"
L40_1.m_Talk_FRA = L41_1
