L45_1 = "CHARADE_ACT4_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 5400401
L44_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "노엘 양은 정말 회복이 빠르군."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ノエル君は本当に立ち直るのが早いな。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Noelle sure recovers fast."
L44_1.m_Talk_ENG = L45_1
L45_1 = "洛艾兒恢復得可真快。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "โนเอลแน่ใจนะว่าไม่เป็นไร"
L44_1.m_Talk_THA = L45_1
L45_1 = "Noelle thật là hồi phục nhanh thật."
L44_1.m_Talk_VTN = L45_1
L45_1 = "诺艾尔恢复得可真快啊。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Noelle rappelt sich echt schnell wieder auf."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Noelle retombe vraiment toujours sur ses pieds."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "CHARADE_ACT4_INTERLUDE1@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5400401
L45_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L45_1.m_Pos = "R"
L46_1 = "오뚜기 같은 거 아냐? 머리에 든 게 적어서 균형을 금방 회복한다거나."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ダルマみたいなもんじゃないか？　頭が軽くて、すぐバランスを取り戻すところとか。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Maybe she's some kind of roly-poly toy. Or she's able to balance herself quickly because her head is so light."
L45_1.m_Talk_ENG = L46_1
L46_1 = "不覺得她很像不倒翁嗎？因為腦袋裡裝的東西少，所以很快就能恢復平衡。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "บางทีเธออาจจะเป็นของเล่นตัวอ้วนๆ หรือเธอสามารถทรงตัวได้อย่างรวดเร็วเพราะศีรษะของเธอเบามาก"
L45_1.m_Talk_THA = L46_1
L46_1 = "Có lẽ nhóc ấy giống con lật đật. Hoặc là có thể tự cân bằng nhanh chóng vì đầu cô ấy chả nghĩ gì cả."
L45_1.m_Talk_VTN = L46_1
L46_1 = "不觉得她很像不倒翁吗？因为脑袋里装的东西少，所以很快就能恢复平衡。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Vielleicht ist sie eine Art Spielzeug. Oder sie kann sich schnell wieder ausbalancieren, weil ihr Kopf so leicht ist."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Ouais, on dirait ce genre de jouets qui basculent. Ou alors... Elle a ce sens de l'équilibre parce que sa tête est très légère."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
