L49_1 = "자! 없는 것 빼고 다 있다! 아포칼립스의 시작!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "さあ！　ここには何でもすべてある！　アポカリプスの始まり！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Now! Here, we have everything, everywhere, all at once! Welcome to the Apocalypse!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "到囉！什麼都賣，什麼都不奇怪的阿波卡利斯商店！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "นี่นี่! ที่นี่มีครบทุกอย่าง พร้อมเพียง! ยินดีต้อนรับสู่คัมภีร์ของศาสนาคริสต์!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Okay! Chúng ta có mọi thứ ở khắp mọi nơi! Chào mừng đến với Apocalypse!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "好了！从天上到地下什么都卖的便利店！末日便利店！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Also gut! Alles ist da, außer dem, was nicht da ist! Willkommen beim Mini-Markt „Apocalypse“!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Bon ! Il y a vraiment tout ce qu'il vous faut ici ! Bienvenue à l'Apocalypse !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
