L51_1[2] = L53_1
L49_1[L50_1] = L51_1
L50_1 = "출입구만 무려 500여 개! 도시 아래 펼쳐진 세계 최대의 스트리트 몰! 브랑겔입니다!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "出入口だけでなんと500か所！　街の下に広がった世界最大のストリートモール！　ウランゲルです！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Five hundred entrances! The world's biggest mall ever made! This is Wrangel!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "光出入口就有500多個！世界最大的地下商場！弗蘭格爾！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ค่าเข้า 500 B ! ห้างสรรพสินค้าที่ใหญ่ที่สุดในโลกที่เคยสร้างมา!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Có tổng cộng năm trăm lối vào! Đây là Wrangel! Trung tâm mua sắm lớn nhất thế giới từng được xây dựng!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "光出入口就有500多个！城市底下的世界最大街头购物中心！兰格尔！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Fünfhundert Eingänge! Das größte Einkaufszentrum der Welt, das jemals erbaut wurde! Das ist Wrangel!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Il y a plus de 500 entrées ! C'est le plus grand centre commercial de rue au monde ! Voici Wrangel !"
L49_1.m_Talk_FRA = L50_1
