L3_1 = "m_Crash"
L2_1[L3_1] = 15
L3_1 = "너 정말 제대로 관광만 다닐 작정이었구나……?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "本当にしっかり観光だけするつもりだったんだね……？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You really went all in on the tourism, didn't you...?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "原來你認真是來旅遊的……？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "การทัศนศึกษาจบแล้วใช่ไหม...?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô thật sự đã lên kế hoạch du lịch rất tỉ mỉ, phải không...?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "你是真的打算好好旅游啊……？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Du wolltest wirklich alle Sehenswürdigkeiten abklappern, oder ...?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Tu étais vraiment à fond dans cette histoire de tourisme..."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "CHARADE_ACT4_INTERLUDE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5400401
L3_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "FELICETTE_CANARY_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "그러게요. 여기서 사는 우리보다 더 잘 아는 것 같아요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そうね。ここに住んでる私たちより詳しいみたいだわ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I know, right? She knows the place better than we do. And we live here."
L3_1.m_Talk_ENG = L4_1
L4_1 = "對啊，比我們這些在地人還熟。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันจะรู้หรอ? เธอรู้จักสถานที่นี้ดีกว่าพวกเรา และพวกเราก็อาศัยอยู่ที่นี่"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hẳn rồi? Cô ấy biết nơi này rõ hơn cả chúng tôi sống ở đây nữa."
L3_1.m_Talk_VTN = L4_1
L4_1 = "是吧？比生活在这里的我们知道的都多。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Nicht wahr? Sie kennt diesen Ort besser als wir, die hier leben."
L3_1.m_Talk_DEU = L4_1
L4_1 = "C'est clair. Elle connaît Charade mieux que nous alors qu'on y vit."
L3_1.m_Talk_FRA = L4_1
