L6_1 = "m_StartFXSoundName"
L7_1 = "FX_CUTSCEN_NOISE"
L5_1[L6_1] = L7_1
L6_1 = "<color=#ffd34c>손님 여러분께 안내 말씀드립니다.</color>"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "<color=#ffd34c>お客さまにご案内いたします。</color>"
L5_1.m_Talk_JPN = L6_1
L6_1 = "<color=#ffd34c>Attention, all visitors.</color>"
L5_1.m_Talk_ENG = L6_1
L6_1 = "<color=#ffd34c>各位顧客，現在播報一則通知。</color>"
L5_1.m_Talk_TWN = L6_1
L6_1 = "<color=#ffd34c>สวัสดี นักท่องเที่ยวทุกท่าน</color>"
L5_1.m_Talk_THA = L6_1
L6_1 = "<color=#ffd34c>Tất cả quý khách xin chú ý.</color>"
L5_1.m_Talk_VTN = L6_1
L6_1 = "<color=#ffd34c>各位顾客，现在播报一则通知。</color>"
L5_1.m_Talk_SCN = L6_1
L6_1 = "<color=#ffd34c>Eine Mitteilung an alle Besucher.</color>"
L5_1.m_Talk_DEU = L6_1
L6_1 = "<color=#ffd34c>À l'attention de tous nos visiteurs.</color>"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "CHARADE_ACT4_INTERLUDE1@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5400401
L6_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "<color=#ffd34c>잠시 후, 사전에 공지드린 대로 저희 브랑겔에서 건틀렛 예선전이 진행될 예정입니다.</color>"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "<color=#ffd34c>この後、事前にご案内しました、ウランゲルにてガントレット予選が開かれる予定でございます。</color>"
L6_1.m_Talk_JPN = L7_1
L7_1 = "<color=#ffd34c>Soon, the qualifiers for the Gauntlet League will be held at Wrangel.</color>"
L6_1.m_Talk_ENG = L7_1
L7_1 = "<color=#ffd34c>如先前通知所說，稍後將在弗蘭格爾進行聖鎧預賽。</color>"
L6_1.m_Talk_TWN = L7_1
L7_1 = "<color=#ffd34c>เร็วๆ นี้ จะมีการแข่งขันรอบคัดเลือก ของลีกกอนต์เล็ต เราจะจัดขึ้นที่ แรงเกล</color>"
L6_1.m_Talk_THA = L7_1
L7_1 = "<color=#ffd34c>Sắp tới, Vòng loại của Giải Gauntlet sẽ được tổ chức tại Wrangel.</color>"
L6_1.m_Talk_VTN = L7_1
L7_1 = "<color=#ffd34c>正如提前通知的那样，稍后将在我们兰格尔进行圣铠预选赛。</color>"
L6_1.m_Talk_SCN = L7_1
L7_1 = "<color=#ffd34c>In Kürze findet die Qualifikationsrunde für die Fehde-Liga in Wrangel statt.</color>"
L6_1.m_Talk_DEU = L7_1
L7_1 = "<color=#ffd34c>Les qualifications de la compétition vont bientôt avoir lieu à Wrangel.</color>"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "CHARADE_ACT4_INTERLUDE1@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5400401
L7_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "<color=#ffd34c>경기 중 지하 2층은 쇼핑이 어렵습니다. 손님 여러분의 이해 부탁드립니다.</color>"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "<color=#ffd34c>試合中、地下2階でのショッピングはご利用できません。ご了承ください。</color>"
L7_1.m_Talk_JPN = L8_1
L8_1 = "<color=#ffd34c>Please be advised that floor B2 will be restricted and unavailable for shopping during the match. We thank you for your cooperation.</color>"
L7_1.m_Talk_ENG = L8_1
L8_1 = "<color=#ffd34c>比賽期間地下2樓將暫時關閉，無法購物，請顧客朋友們予以諒解。</color>"
L7_1.m_Talk_TWN = L8_1
L8_1 = "<color=#ffd34c>ประกาศ ชั้น B2 จะถูกปิดอยู่ในเขตจำกัดและไม่สามารถซื้อของได้ในช่วงเวลาการแข่งขัน ขออภัยในความไม่สะดวก และขอบคุณที่ให้ความร่วมมือ</color>"
L7_1.m_Talk_THA = L8_1
L8_1 = "<color=#ffd34c>Xin lưu ý rằng tầng B2 sẽ bị hạn chế mua sắm trong thời gian trận đấu diễn ra. Xin chân thành cảm ơn sự hợp tác của bạn.</color>"
L7_1.m_Talk_VTN = L8_1
L8_1 = "<color=#ffd34c>比赛期间地下2楼将暂时关闭，无法购物，请顾客朋友们予以谅解。</color>"
L7_1.m_Talk_SCN = L8_1
L8_1 = "<color=#ffd34c>Bitte beachten Sie, dass während des Spiels das zweite Untergeschoss nicht betreten werden kann. Wir danken Ihnen für Ihr Verständnis.</color>"
L7_1.m_Talk_DEU = L8_1
L8_1 = "<color=#ffd34c>Veuillez noter que l'étage -2 sera fermé pendant toute la durée du match. Merci de votre compréhension.</color>"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
