L10_1 = "CHARADE_ACT4_INTERLUDE1@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5400401
L9_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "그럼 안 되죠! 다들 늦기 전에 지하 2층부터 가요! 어서요!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "そんなのダメです！　皆さん、地下2階から行きましょう！　早く！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I won't allow it! Everyone, head to floor B2! NOW!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "那可不行！時間很趕欸！大家快去地下2樓，快點！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ไม่อนุญาตรึ! ทุกคน เราไปชั้น B2 กัน! ตอนนี้เลย!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Không được! Mọi người, lên tầng B2! NGAY!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "那可不行！大家快去地下2楼，不然就来不及了！抓紧时间！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Das geht doch nicht! Alle zusammen, auf ins zweite Untergeschoss! Schnell!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Alors là, c'est non ! Vite ! Tout le monde à l'étage -2 !"
L9_1.m_Talk_FRA = L10_1
