L11_1 = "이 다음은 대관람차거든요! 시내 한가운데 세워졌다는데 SNS에서 핫 플레이스에요!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "この次は大観覧車ですよ！　市内の真ん中に建てられたらしいんですけど、SNSで話題のスポットなんです！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Next is the Ferris wheel! Located in the heart of downtown, it's a social media hot spot!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "下一站是摩天輪！據說就蓋在市中心，是熱門打卡地點！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ต่อไปก็ชิงช้าสวรรค์! ตั้งอยู่ใจกลางเมืองเป็นจุดที่นิยมมากในโซเชียลมีเดีย!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Tiếp theo là bánh xe Ferris! Đó là một điểm nổi tiếng trên mạng xã hội, nằm ở trung tâm của trung tâm thành phố!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "下一站是摩天轮！据说建在市中心，是SNS上的热门打卡地！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Nächster Halt ist das Riesenrad! Es liegt im Herzen der Innenstadt und ist ein Social-Media-Hotspot!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Prochaine étape : la Grande Roue ! Située au coeur du centre ville, elle fait un carton sur les réseaux sociaux !"
L10_1.m_Talk_FRA = L11_1
