L19_1 = "히야, 하루만에 도시를 다 돌아본 기분이네."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "いやあ、一日で街を全部見て回った気分だよ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Whew, it feels like we've gone around the whole city in one day."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哎呀，有種一天就把整個城市都逛遍的感覺。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ว้าววว เหมือนได้เที่ยวทั่วเมืองในวันเดียวเลย"
L18_1.m_Talk_THA = L19_1
L19_1 = "Phù, có cảm giác như chúng ta đã đi khắp thành phố trong một ngày ấy."
L18_1.m_Talk_VTN = L19_1
L19_1 = "哎呀，有种一天就把整个城市都逛遍了的感觉。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Puh, es fühlt sich an, als hätten wir an nur einem Tag die ganze Stadt erkundet."
L18_1.m_Talk_DEU = L19_1
L19_1 = "J'ai vraiment l'impression d'avoir fait tout le tour de la ville en une journée."
L18_1.m_Talk_FRA = L19_1
