L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "L"
L20_1 = "난 마지막 관람차가 제일 좋았어. 역시 그 특유의 분위기가 매력적이라고 해야 하나."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私は最後の観覧車がよかったなあ。やっぱりあの特有の雰囲気が魅力的って感じ？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I liked the Ferris wheel best. The atmosphere there feels so special."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我喜歡最後的摩天輪。那種獨特的氛圍很吸引人。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฉันชอบชิงช้าสวรรค์ที่สุด บรรยากาศนี่ให้ความรู้สึกพิเศษมาก"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi thích bánh xe Ferris nhất. Không khí ở đó cảm thấy rất đặc biệt."
L19_1.m_Talk_VTN = L20_1
L20_1 = "我喜欢最后的摩天轮。那种独特的氛围很吸引人。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Mir gefiel das Riesenrad am besten. Die Atmosphäre dort war unvergleichbar schön."
L19_1.m_Talk_DEU = L20_1
L20_1 = "J'ai adoré la Grande Roue. L'ambiance y était vraiment... Unique."
L19_1.m_Talk_FRA = L20_1
