L22_1 = "하아, 이 놈의 업무 알람. 하여간 기분 망치는 데 선수라니까."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "はあ、この仕事アラーム。もう、雰囲気を台無しにするんだから。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Geez, all these work notifications. They just have to ruin my mood, don't they?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "哀哀，這個可惡的工作鬧鐘，真會破壞心情。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เหอะ การแจ้งเตือนนั่น พวกเขาต้องการทำลายอารมณ์ของฉัน  งั้นหรอ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ôi, mấy thông báo công việc này. Thật là biết phá hỏng tâm trạng của tôi!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "啊，这个可恶的工作闹钟，真会破坏心情。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Meine Güte, all diese Arbeitsbenachrichtigungen. Diese Typen haben es wirklich drauf, meine Laune zu ruinieren ..."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Ah, j'ai tout un tas de notifications pour le boulot. Parfait pour casser l'ambiance."
L21_1.m_Talk_FRA = L22_1
