L24_1 = "MINA_FENRIR_CHIEF_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "안내하느라 고생했어, 노엘. 야경이 정말 멋지더라."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "案内ご苦労様、ノエル。夜景が本当に素敵だった。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Thanks for showing us around, Noelle. The night view was great."
L23_1.m_Talk_ENG = L24_1
L24_1 = "帶我們逛一整天辛苦囉，洛艾兒。夜景真的很漂亮。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ขอบคุณที่พาเราไปเที่ยวรอบ ๆ นะโนเอล วิวกลางคืนคือดีมาก"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cảm ơn đã dẫn chúng tôi đi chơi, Noelle. Cảnh đêm đẹp lắm."
L23_1.m_Talk_VTN = L24_1
L24_1 = "导游工作辛苦了，诺艾尔。夜景真的很漂亮。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Danke, dass du uns herumgeführt hast, Noelle. Die Aussicht bei Nacht war wirklich atemberaubend schön."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Merci pour tout, Noelle. La vue de nuit était vraiment superbe."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "CHARADE_ACT4_INTERLUDE1@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5400401
L24_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
