L24_1.m_Face = "UNIT_PRIDE"
L24_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L24_1.m_Pos = "C"
L25_1 = "천만에요, 미나 선배. 첫 날 일정은 몸풀기라구요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "どういたしまして、ミナ先輩。初日のスケジュールは準備運動ですよ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "My pleasure, Mina. The first day is only a sneak peek!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "不客氣，米娜前輩。第一天的行程只是暖身而已。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ด้วยความยินดีจ้ามีนา วันแรกก็ได้แอบดูละ!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Chị Mina đừng khách sao. Ngày đầu tiên chỉ là khởi động chút thôi."
L24_1.m_Talk_VTN = L25_1
L25_1 = "不客气，米娜前辈。第一天的日程就是热身。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Gern geschehen, Mina. Der erste Tag war nur ein kleiner Vorgeschmack!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je vous en prie, Mina. Et ce n'était qu'un aperçu."
L24_1.m_Talk_FRA = L25_1
