L25_1.m_Pos = "C"
L26_1 = "이틀째 일정부터는 더 어마어마한 것들로 준비해 뒀어요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "二日目のスケジュールからは、もっとすごいものを用意してます。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "On day 2, the tour will be packed with even more special attractions!"
