L26_1 = "從第二天的行程開始，我還有準備更驚人的內容！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ในวันที่ 2 ทัวร์จะเต็มไปด้วยสถานที่ท่องเที่ยวพิเศษมากยิ่งขึ้น!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Vào ngày thứ 2, chúng ta sẽ đi coi nhiều điểm tham quan đặc biệt hơn nữa!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "从第二天的日程开始，我准备了更惊人的项目！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Für den zweiten Tag habe ich noch viel mehr außergewöhnliche Attraktionen eingeplant!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Demain, notre programme va être encore plus chargé."
