L26_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "금융 센터에, 비행선, 우주 공항! 아직 못 가 본 맛집들까지!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "金融センターに、飛行船、宇宙港！　まだ行けていないグルメ店まで！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Finance centers, airships, space stations! Even more must-visit restaurants!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "金融中心、飛船、航太站！還有沒去過的美食店！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ศูนย์การเงิน ยานอาวกาศ สถานีอวกาศ! ร้านที่ต้องไปแวะเพิ่มเติม!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Trung tâm tài chính, khí cầu, trạm vũ trụ! Cả nhà hàng phải nếm thử nữa!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "金融中心、飞船、航天站！还有没去过的美食店！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Finanzzentren, Luftschiffe, Raumstationen! Noch mehr Restaurants, die man unbedingt besuchen muss!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Le centre des finances, le dirigeable, la station spatiale ! Et encore plus de restaurants !"
L26_1.m_Talk_FRA = L27_1
