L31_1 = "ADMIN_COFFIN_NULL_QM"
L30_1.m_CharStrID = L31_1
L31_1 = "관람차가 무서웠나?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "観覧車が怖かったのか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Were you scared back on the Ferris wheel?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "你害怕摩天輪嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "คุณจะกลับไปขึ้นชิงช้าสวรรค์น่ากลัวนั่นอีกไหม?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô có sợ khi đu quay không?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "你害怕摩天轮吗，菲利塞特？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Hattest du auf dem Riesenrad Angst?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu as eu peur sur la Grande Roue ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "CHARADE_ACT4_INTERLUDE1@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5400401
L31_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_SURPRISE"
L31_1.m_Face = L32_1
L32_1 = "FELICETTE_CANARY_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "m_Crash"
L31_1[L32_1] = 15
L32_1 = "그, 그런 건 아니에요. 이 나이에 높은 곳을 무서워할 리 없잖아요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そ、そんなんじゃありません。この歳で高いところが怖いわけないでしょう？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "O-of course not. I'm too old to be afraid of heights."
L31_1.m_Talk_ENG = L32_1
L32_1 = "不，不是的，我這個年紀怎麼會怕高。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "นะ- แน่นอนไม่ ฉันแก่เกินไปที่และกลัวความสูง"
L31_1.m_Talk_THA = L32_1
L32_1 = "T-tất nhiên là không. Tôi lớn thế này sao mà sợ độ cao được."
L31_1.m_Talk_VTN = L32_1
L32_1 = "不、不是的，我都这么大了，怎么会怕高。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "N-natürlich nicht. Ich bin viel zu alt, um noch Höhenangst zu haben."
L31_1.m_Talk_DEU = L32_1
L32_1 = "M-Mais non. Je ne suis pas une gamine, j'ai pas le vertige."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
