L33_1 = "그냥……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ただ……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It's just that..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "只是……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แค่นั้น..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Chỉ là..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "只是……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es ist nur so, dass ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "C'est juste que..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "CHARADE_ACT4_INTERLUDE1@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5400401
L33_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "FELICETTE_CANARY_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "……그냥. 지시 내려 줘서 고맙다고요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "……ただ。指示を出してくれてありがとうございます。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "...I just wanted to thank you for giving us the instruction today."
L33_1.m_Talk_ENG = L34_1
L34_1 = "……我只是想謝謝你今天的指示。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "...ฉันแค่อยากจะขอบคุณสำหรับการจองของเราในวันนี้"
L33_1.m_Talk_THA = L34_1
L34_1 = "...Tôi chỉ muốn cảm ơn ngài hôm nay đã chỉ đạo như vậy."
L33_1.m_Talk_VTN = L34_1
L34_1 = "……我只是想谢谢你今天的指示。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "... Ich wollte Ihnen nur dafür danken, dass Sie uns heute diese Anweisung gegeben haben."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je voulais juste vous remercier pour cette journée..."
L33_1.m_Talk_FRA = L34_1
