L37_1 = "CHARADE_ACT4_INTERLUDE1@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5400401
L36_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_LAUGH"
L37_1 = "FELICETTE_CANARY_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "L"
L37_1 = "가끔 이런 식으로 시간 낭비 하는 것도 즐겁네요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "たまにこんな風に時間を潰すのも楽しいですね。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Sometimes, I guess it's nice to waste time like this."
L36_1.m_Talk_ENG = L37_1
L37_1 = "偶爾這樣浪費一下時間也很開心。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "บางครั้งฉันคิดว่ามันเป็นเรื่องดีถ้าจะเสียเวลาแบบนี้บ้าง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đôi khi, cũng thật vui khi lãng phí thời gian như thế này."
L36_1.m_Talk_VTN = L37_1
L37_1 = "偶尔这样浪费一下时间也很开心。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Es kann manchmal auch schön sein, auf diese Weise seine Zeit zu verschwenden."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Je suppose que parfois, ça fait du bien de perdre du temps comme ça."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "CHARADE_ACT4_INTERLUDE1@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5400401
L37_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L37_1.m_Pos = "R"
L38_1 = "고마우면 그냥 고맙다고 할 것이지, 괜히 토 달고 앉았네."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "感謝してるならありがとうって言えばいいのに、なんで一言多いんだ？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Just finish at thank you, you ungrateful child."
L37_1.m_Talk_ENG = L38_1
L38_1 = "想謝謝就直說嘛，幹嘛在那欲言又止的。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "จบด้วยคำขอบคุณนะเจ้าเด็กอกตัญญู"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nếu cảm ơn thì phải nói cho hẳn hoi, đứa trẻ vô ơn."
L37_1.m_Talk_VTN = L38_1
L38_1 = "想谢谢就直说啊，还非要绕来绕去的。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sag doch einfach „Danke“, du undankbares Gör."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Dis juste merci, ingrate."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "CHARADE_ACT4_INTERLUDE1@188#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 188
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5400401
L38_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_Face = "UNIT_LAUGH"
L38_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L38_1.m_Pos = "R"
L39_1 = "그런데 오늘 너무 무리한 거 아냐? 뇌물 주기도 빠듯할 텐데."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "でも、今日無理しすぎたんじゃないか？　賄賂をくばるだけでもキツイだろ？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "By the way, aren't you going over your budget today? The budget must be pretty tight with all that bribing."
L38_1.m_Talk_ENG = L39_1
L39_1 = "不過會不會太打腫臉充胖子？要賄賂的錢應該也很吃緊吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "วันนี้เธอใช้จ่ายเกินงบไปหรือเปล่า เธอต้องจ่ายเยอะแน่เลยกับการติดสินบนทั้งหมด"
L38_1.m_Talk_THA = L39_1
L39_1 = "Mà hôm nay ngài không vượt quá ngân sách chứ? Ngân sách hẳn khá eo hẹp với mấy khoản hối lộ đó."
L38_1.m_Talk_VTN = L39_1
L39_1 = "不过经费是不是太勉强了？行贿的钱也有点紧张呢。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Übrigens, hast du das Budget heute nicht ziemlich überstrapaziert? Du dürftest doch wegen all der Bestechungsgelder ziemlich knapp bei Kasse sein."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Au fait, on a pas dépassé le budget ? Avec tous ces pots-de-vin..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
