L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_LAUGH"
L44_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "있잖아. 심판들한테 조금씩 찔러 주는 거."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ほら。審判にちょっとずつあげるやつ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You know, the stuff you give to the judges."
L44_1.m_Talk_ENG = L45_1
L45_1 = "明知故問欸～就是稍微買通一下裁判嘛。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เธอรู้ไหม ของที่เธอให้กับผู้ดูแล"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ngài biết đấy, những thứ ngài sẽ đưa cho ban giám khảo."
L44_1.m_Talk_VTN = L45_1
L45_1 = "不是有那种嘛，稍微贿赂一下裁判们。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Na klar. Um bei den Juroren einen guten Eindruck zu hinterlassen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ben oui, ce que vous donnez aux juges."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "CHARADE_ACT4_INTERLUDE1@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5400401
L45_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "스키너 말처럼 여긴 룰 위반도 들키지만 않으면 그만이거든. 로비 정도면 신사적이지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "スキナーの言うとおり、ここはルール違反もバレなければいいんだよ。ロビー活動ぐらいなら紳士的だろ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Like Skinner said, it's okay as long as you don't get caught. Lobbying is pretty mild, to be honest."
L45_1.m_Talk_ENG = L46_1
L46_1 = "史金納不是有說，就算犯規，只要不被發現就沒問題。花錢買通算是比較斯文的做法吧？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เหมือนที่สกินเนอร์พูด ไม่เป็นไร ตราบใดที่เธอไม่ถูกจับได้ "
L45_1.m_Talk_THA = L46_1
L46_1 = "Giống như Skinner đã nói, miễn ngài không bị bắt khi phạm luật là được. Thành thật mà nói, vận động hành lang khá nhẹ nhàng."
L45_1.m_Talk_VTN = L46_1
L46_1 = "就像斯金纳说的那样，在这里哪怕犯规，只要不被发现就没问题。行贿的话很绅士了。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Wie Skinner bereits gesagt hat, ist es in Ordnung, hier gegen die Regeln zu verstoßen, solange man nicht erwischt wird. Der Lobbyismus ist hier ziemlich gemäßigt."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Comme Skinner dit, c'est ok tant qu'on se fait pas prendre. Le lobbying, ça reste courtois."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
