L49_1 = "UNIT_SURPRISE"
L48_1.m_Face = L49_1
L48_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L48_1.m_Pos = "R"
L49_1 = "……설마 안 줬어?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……まさか、あげてないのか？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "You're not saying... that you didn't bribe anyone, are you?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "……你難道沒給？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "เธอไม่ได้บอก...เธอไม่ได้ติดสินบนใครใช่ไหม?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Chẳng lẽ... Ngài chưa hối lộ ai sao?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "……你难道没给？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "... Hast du sie etwa nicht bestochen?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ne me dites pas que... Vous soudoyez personne ?"
L48_1.m_Talk_FRA = L49_1
