L51_1 = "MARK7"
L50_1.m_ActionStrKey = L51_1
L51_1 = "딱히 불법적인 방법을 선호했던 적은 없어서."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "別に、不法的なやり方は好きではないからな。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I never took a liking for illegal methods."
L50_1.m_Talk_ENG = L51_1
L51_1 = "我不是很喜歡非法的手段。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ผมไม่ค่อยเคยชอบวิธีการที่ผิดกฎหมาย"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi chưa bao giờ thích phương pháp bất hợp pháp."
L50_1.m_Talk_VTN = L51_1
L51_1 = "我不是很喜欢非法的手段。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich war noch nie ein großer Fan von illegalen Methoden."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Je n'aime pas trop tout ce qui est illégal."
L50_1.m_Talk_FRA = L51_1
