L2_1 = "CHARADE_ACT4_INTERLUDE1@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5400401
L1_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_SERIOUS"
L1_1.m_Action = "MARK"
L2_1 = "MARK7"
L1_1.m_ActionStrKey = L2_1
L1_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L1_1.m_Pos = "R"
L2_1 = "아니, 흑막처럼 생겼으면서 왜 바른 생활 청년 같은 소릴 하고 있어?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "いや、黒幕みたいな顔して何を堅実な若者みたいなこと言ってるんだよ？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "You look exactly like the typical final boss. Why are you starting all this ethical crap?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "等等，你一看就是幕後大Boss的感覺，怎麼會發出這種正義之聲？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "เธอดูเหมือนกับบอสทุกประการ ทำไมเธอถึงเริ่มเรื่องไร้สาระทั้งหมดนี้?"
L1_1.m_Talk_THA = L2_1
L2_1 = "Ngài trông giống hệt như BOSS cuối vậy. Tại sao ngài lại nói mấy thứ đạo đức này?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "不是，你一看就是幕后大boss的感觉，怎么会有这种正直的发言？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Du siehst genauso aus wie der typische Endgegner, also warum tust du jetzt so, als würdest du ein aufrichtiges und anständiges Leben führen?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais tu as le look typique du mafieux ! Pourquoi toute cette éthique ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "CHARADE_ACT4_INTERLUDE1@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5400401
L2_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_PRIDE"
L3_1 = "FELICETTE_CANARY_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "L"
L3_1 = "그럼 저희가 이긴 경기 모두 편파 판정은 없었다는 거네요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "それじゃあ、私たちが勝利した試合はみんな、正しく判定されてたってことですね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That means our victories were all fair and square."
L2_1.m_Talk_ENG = L3_1
L3_1 = "意思是，我們贏得光明正大。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "นั่นหมายความว่าชัยชนะของเราทั้งหมดมีทั้งยุติธรรมและเล่ห์เหลี่ยม"
L2_1.m_Talk_THA = L3_1
L3_1 = "Điều đó tức là những chiến thắng của chúng ta đều công bằng và chính trực."
L2_1.m_Talk_VTN = L3_1
L3_1 = "那也就是说，我们赢的所有比赛都没有水分。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das bedeutet also, dass es in keinem der Spiele, die wir gewonnen haben, voreingenommene Entscheidungen gab."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Ça veut donc dire que toutes nos victoires étaient méritées."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "CHARADE_ACT4_INTERLUDE1@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5400401
L3_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "FELICETTE_CANARY_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "오히려 훨씬 불리한 상황에서 싸워 이긴 거였어요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "むしろ、もっと不利な状況で戦って勝っていたんだわ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "We won, even with the disadvantage."
L3_1.m_Talk_ENG = L4_1
L4_1 = "而且還是在對我們不利的情況下獲勝的。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เราจะต้องชนะแม้จะเสียเปรียบก็ตาม"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chúng ta đã thắng, ngay cả khi gặp bất lợi."
L3_1.m_Talk_VTN = L4_1
L4_1 = "相反，我们是在更不利的情况下战斗并获胜的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Vielmehr haben wir sogar in ungünstigeren Situationen gekämpft und dennoch gewonnen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "On a gagné, même avec nos désavantages."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
