L4_1.m_fTalkTime = 0.03
L5_1 = "これって喜ぶべきことなのか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Are you sure you should be happy about this?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "現在這是值得高興的事嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เธอแน่ใจหรอว่าเธอจะมีความสุขกับเรื่องนี้?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhóc chắc là bây giờ nên vui sao?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "现在这是值得高兴的事吗？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ist das jetzt etwas, worüber man sich freuen sollte? "
L4_1.m_Talk_DEU = L5_1
L5_1 = "Tu es sure que c'est quelque chose dont on doit se réjouir ?"
