L8_1 = "방금 전 관리국 건틀렛 운영회에서 보낸 메일이에요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "先ほど管理局のガントレット運営会が送ったメールです。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "The Administration Gauntlet Committee sent us an email."
L7_1.m_Talk_ENG = L8_1
L8_1 = "這是剛才管理局聖鎧委員會發來的郵件。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "คณะกรรมการจากกอนต์เล็ตส่งอีเมลถึงเรา"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ủy ban Gauntlet Cục Quản Lý đã gửi một email."
L7_1.m_Talk_VTN = L8_1
L8_1 = "这是刚才管理局圣铠委员会发来的邮件。"
