L11_1 = "CHARADE_ACT4_INTERLUDE1@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5400401
L10_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "<color=#ffd34c>……검토 결과, 운영회는 그릴 파티가 제출한 사유에 대해 정당하다고 판단하였습니다.</color>"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "<color=#ffd34c>……検討の結果、運営会はグリルパーティーが提出した理由が正当であると判断しました。</color>"
L10_1.m_Talk_JPN = L11_1
L11_1 = "<color=#ffd34c>...The Committee recognizes that the reason submitted by Grill Party is valid.</color>"
L10_1.m_Talk_ENG = L11_1
L11_1 = "<color=#ffd34c>……根據審查結果，委員會認為格里爾派提提交的理由正當合理。</color>"
L10_1.m_Talk_TWN = L11_1
L11_1 = "<color=#ffd34c>...คณะกรรมการชี้แจงว่าเหตุผลที่กลิลปาร์ตี้ส่งมานั้นถูกต้อง</color>"
L10_1.m_Talk_THA = L11_1
L11_1 = "<color=#ffd34c>...Ủy ban cho rằng lý do đưa ra bởi Grill Party là hợp lý.</color>"
L10_1.m_Talk_VTN = L11_1
L11_1 = "<color=#ffd34c>……根据审核结果，委员会认为格利尔提交的理由正当合理。</color>"
L10_1.m_Talk_SCN = L11_1
L11_1 = "<color=#ffd34c>... Als Ergebnis der Untersuchung kam der Ausschuss zu dem Schluss, dass die von der Grill Party vorgebrachten Gründe gerechtfertigt waren.</color>"
L10_1.m_Talk_DEU = L11_1
L11_1 = "<color=#ffd34c>...Le comité reconnaît que la raison présentée par l'équipe Barbecue est valable.</color>"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "CHARADE_ACT4_INTERLUDE1@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5400401
L11_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "<color=#ffd34c>따라서 엔트리 조정을 허가하였으며, 경기는 정상 진행됩니다.</color>"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "<color=#ffd34c>よって、エントリー調整を許可し、試合は正常に進行されます。</color>"
L11_1.m_Talk_JPN = L12_1
L12_1 = "<color=#ffd34c>Therefore, we have approved their request to change the entry list. All matches will be held as scheduled.</color>"
L11_1.m_Talk_ENG = L12_1
L12_1 = "<color=#ffd34c>故允許其調整參賽人員，比賽將如期進行。</color>"
L11_1.m_Talk_TWN = L12_1
L12_1 = "<color=#ffd34c>ดังนั้นเราจึงอนุมัติคำขอเปลี่ยนรายการของพวกเขา การแข่งขันทั้งหมดจะจัดขึ้นตามกำหนดการ</color>"
L11_1.m_Talk_THA = L12_1
L12_1 = "<color=#ffd34c>Vì vậy, chúng tôi đã chấp thuận yêu cầu thay đổi danh sách người chơi của họ. Tất cả các trận đấu sẽ được tổ chức theo kế hoạch.</color>"
L11_1.m_Talk_VTN = L12_1
L12_1 = "<color=#ffd34c>故允许其调整参赛人员，比赛将如期进行。</color>"
L11_1.m_Talk_SCN = L12_1
L12_1 = "<color=#ffd34c>Daher wurden die Änderungen bezüglich der Teilnehmerliste genehmigt und alle Spiele werden wie geplant stattfinden.</color>"
L11_1.m_Talk_DEU = L12_1
L12_1 = "<color=#ffd34c>Par conséquent, nous avons approuvé leur demande de modifier la liste des participants. Tous les matchs se dérouleront comme prévu.</color>"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "CHARADE_ACT4_INTERLUDE1@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5400401
L12_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "<color=#ffd34c>또한 경기 흥행을 위해 암전 기믹을 도입할 예정이므로….</color>"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "<color=#ffd34c>また、試合の興行のために、暗転ギミックを導入する予定ですので……</color>"
L12_1.m_Talk_JPN = L13_1
L13_1 = "<color=#ffd34c>Additionally, there will be a lights-out gimmick for the viewers' entertainment and...</color>"
L12_1.m_Talk_ENG = L13_1
L13_1 = "<color=#ffd34c>另外，為提高比賽的吸引力，預計將引進夜戰機關……</color>"
L12_1.m_Talk_TWN = L13_1
L13_1 = "<color=#ffd34c>นอกจากนี้ จะมีพลุแสงไฟเพื่อสร้างความบันเทิงแก่ผู้ชมและ...</color>"
L12_1.m_Talk_THA = L13_1
L13_1 = "<color=#ffd34c>Ngoài ra, để thu hút người xem, chúng tôi xin giới thiệu chế độ tắt đèn...</color>"
L12_1.m_Talk_VTN = L13_1
L13_1 = "<color=#ffd34c>另外，为提高比赛的吸引力，计划引进夜战机关……</color>"
L12_1.m_Talk_SCN = L13_1
L13_1 = "<color=#ffd34c>Darüber hinaus planen wir die Einführung eines Tricks, bei dem das Licht ausgeht, um das Spiel unterhaltsamer zu gestalten ...</color>"
L12_1.m_Talk_DEU = L13_1
L13_1 = "<color=#ffd34c>En outre, il y aura une extinction des lumières pour divertir nos spectateurs et...</color>"
L12_1.m_Talk_FRA = L13_1
