L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "기존 팀원들이 출전하기 어려우니까 엔트리를 바꾼다고? 경기 하루 전에?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "既存のチームメンバーが出場できないから、エントリーを変える？　試合の前日に？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "They're changing the entry list because the original players can't play? Last minute I might add?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "因為原來的隊員參賽有困難，所以變更參賽人員？還是在比賽一天前？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "พวกเขากำลังเปลี่ยนรายชื่อเพราะผู้เล่นเดิมที่เล่นไม่ได้? นาทีสุดท้ายที่ฉันอาจเพิ่มอะไร?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Chúng đổi danh sách đội vì những người chơi cũ không chơi được? Lại còn ngay trước ngày thi đấu?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "因为原来的队员参赛有困难，所以变更参赛人员？还是在比赛一天前？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Sie ändern die Teilnehmerliste, weil die eigentlichen Spieler nicht mithalten können? Einen Tag vor dem Spiel?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ils changent leur liste de participants à la dernière minute, comme ça ?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
