L18_1 = "FELICETTE_CANARY_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "이러면 전력 분석도, 연습했던 전술도……"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "これじゃあ戦力の分析も、練習した戦術も……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Everything we did, the analysis, the strategies..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "這樣的話，戰力分析和戰術練習……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เราต้องทำทุกสิ่งใน การวิเคราะห์ กลยุทธ์..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Mọi thứ chúng tôi đã làm, phân tích, chiến lược..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "这样的话，战力分析和战术练习……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Alles, was wir vorbereitet haben, die Analyse, die Strategien ..."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Toutes nos analyses, nos stratégies..."
L17_1.m_Talk_FRA = L18_1
