L21_1 = "CHARADE_ACT4_INTERLUDE1@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5400401
L20_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "ADMIN_COFFIN_NULL_QM"
L20_1.m_CharStrID = L21_1
L21_1 = "그릴 파티에서 손을 쓴 건가?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "グリルパーティーが手を回したのか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Is Grill Party planning something?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "是格里爾派提搞的鬼嗎？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "กริลปาร์ตี้กำลังวางแผนอะไรบางอย่างอยู่หรือเปล่า?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Grill Party ủ mưu gì chăng?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "是格利尔搞的鬼吗？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Hat Grill Party irgendetwas vor?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Vous pensez qu'ils préparent quelque chose ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "CHARADE_ACT4_INTERLUDE1@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5400401
L21_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_DESPAIR"
L22_1 = "STAFF_CANARY_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "아마도요. 이렇게까지 대범하게 일을 벌일 만한 곳은 아니긴 한데…."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "たぶんそうです。ここまで大胆にことを運ぶほどの場所ではないですけど……"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Probably. They're not one to do things this boldly, though..."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我猜是的，雖然單憑他們不可能有這麼大的動作……"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อาจจะ พวกเขาไม่น่าใช่คนที่ทำสิ่งนี้อย่างเด็ดเดี่ยว นั่นอาจจะ..."
L21_1.m_Talk_THA = L22_1
L22_1 = "Hẳn là vậy. Tuy nhiên, chúng không có gan để làm  việc này..."
L21_1.m_Talk_VTN = L22_1
L22_1 = "估计是。虽然仅凭他们不可能有这么大的动作……"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wahrscheinlich. Sie gehören allerdings nicht zu den Leuten, die ein allzu großes Risiko eingehen würden ..."
L21_1.m_Talk_DEU = L22_1
L22_1 = "C'est probable. Mais ils ne sont pas du genre à faire quoi que ce soit d'audacieux..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "CHARADE_ACT4_INTERLUDE1@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5400401
L22_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_SERIOUS"
L22_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "놈들은 잘 쳐 줘도 2류야. 우리가 모르는 뒷배가 있겠지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "やつらは高く評価しても二流だ。私たちの知らない後ろ盾があるんだろ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "They're bush league, at best. They must've gotten some kind of help."
L22_1.m_Talk_ENG = L23_1
L23_1 = "他們再厲害也不過是二流勢力，背後一定有我們不知道的靠山。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "พวกเขาเป็นลีกที่คุณภาพแย่ หรือพวกเขาอาจได้รับความช่วยเหลือบางอย่างอยู่"
L22_1.m_Talk_THA = L23_1
L23_1 = "Chúng giỏi nhất cũng chỉ là tầm giải nhỏ thôi. Chắc hẳn sau lưng có ô dù rồi."
L22_1.m_Talk_VTN = L23_1
L23_1 = "就算打得再好顶多也就是二流势力。他们背后肯定有我们不知道的靠山。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Auch wenn sie gut spielen, sind sie dennoch nur zweitklassig. Es könnte sein, dass sie von irgendjemandem Hilfe erhalten haben."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ces types ne valent rien. Ils ont du recevoir de l'aide ou quelque chose dans le genre."
L22_1.m_Talk_FRA = L23_1
