L26_1 = "CHARADE_ACT4_INTERLUDE1@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5400401
L25_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "UNIT_SURPRISE"
L25_1.m_Face = L26_1
L25_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L25_1.m_Pos = "R"
L26_1 = "m_Crash"
L25_1[L26_1] = 20
L26_1 = "그럼 어떡해요? 내일이 경기인데 사람을 새로 구할 수도 없잖아요!"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "じゃあ、どうしましょう？　試合は明日なのに、新しい人を探すこともできないじゃないですか！"
L25_1.m_Talk_JPN = L26_1
L26_1 = "What do we do, then? It's too late to get someone new!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "那怎麼辦？明天就要比賽咧，我們也不可能重新找人吧！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "แล้วเราจะทำอย่างไร? มันสายเกินไป ที่เราจะหาแผนใหม่!"
L25_1.m_Talk_THA = L26_1
L26_1 = "Thế phải làm sao đây? Đã quá muộn để tìm người mới rồi!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "那怎么办？明天就比赛了，我们也不能重新找人啊！"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Was sollen wir tun? Das Spiel findet bereits morgen statt und wir können so spontan keine neuen Leute mehr einstellen!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Qu'est-ce qu'on va faire ? Le match est demain, il est trop tard pour trouver de nouvelles recrues !"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "CHARADE_ACT4_INTERLUDE1@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5400401
L26_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "MINA_FENRIR_CHIEF_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L27_1 = "관리국에 항의할 수는 없는 거야?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "管理局に抗議できないの？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Can't we file a complaint to the Administration?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "不能向管理局抗議嗎？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เราไม่สามารถยื่นคำร้องต่อองค์การบริหารโลกได้บ้างหรอ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Chúng ta không thể nộp đơn khiếu nại lên Cục Quản Lý sao?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "不能向管理局抗议吗？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Können wir nicht eine Beschwerde bei der Administration einreichen?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "On pourrait pas déposer une plainte auprès de l'Administration ?"
L26_1.m_Talk_FRA = L27_1
