L30_1 = "CHARADE_ACT4_INTERLUDE1@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5400401
L29_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_DESPAIR"
L30_1 = "STAFF_CANARY_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "R"
L30_1 = "규정상으로 문제는 안 돼. 속이 뻔히 보여서 그렇지."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "規定上では問題ないからね。白々しくてムカつくだけで。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Theoretically, we can. It's just too obvious."
L29_1.m_Talk_ENG = L30_1
L30_1 = "從規定上來說是沒問題的，只是他們的用意很明顯。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ในทางทฤษฎี เรายื่นได้ แต่มันชัดเจนเกินไป"
L29_1.m_Talk_THA = L30_1
L30_1 = "Về mặt lý thuyết, chúng ta có thể. Vì mục đích của chúng quá rõ ràng."
L29_1.m_Talk_VTN = L30_1
L30_1 = "从规定上来说是没问题的。只是他们的用心很明显。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Theoretisch schon. Aber es wäre viel zu offensichtlich."
L29_1.m_Talk_DEU = L30_1
L30_1 = "On pourrait, en théorie. Mais à quoi bon ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "CHARADE_ACT4_INTERLUDE1@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5400401
L30_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "STAFF_CANARY_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L31_1 = "누가 관여했는지 조사하려면 한참 걸릴 테고, 뇌물 때문이란 판결이 없는 상황에선……."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "誰が関与したか調査するには結構時間がかかるだろうし、賄賂のせいだという決定打がない状況では……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "It's gonna take ages to find out who's behind this, and with no evidence of lobbying..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "調查需要很長時間，加上沒有確切的證據證明他們有行賄……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ต้องใช้เวลานานเพื่อหาว่าใครอยู่เบื้องหลังเรื่องนี้ และว่าไม่มีการล็อบบี้เกิดขึ้น..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Sẽ mất nhiều thời gian để tìm ra kẻ đứng đằng sau chuyện này, và cũng không có bằng chứng về việc hối lộ..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "调查需要很长时间，加之没有明显的行贿证据……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Es wird ewig dauern, herauszufinden, wer dahinter steckt, und es gibt keine Beweise für Lobbyismus ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ça va prendre des siècles de trouver qui est derrière tout ça. Et puis sans preuves..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "CHARADE_ACT4_INTERLUDE1@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5400401
L31_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "LAIKA_CANARY_NULL_NULL"
L31_1.m_Pos = "L"
L32_1 = "흥. 우리 같은 풋내기들은 그냥 내년도 예선 시드권만 주고 대기시킬걸."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "フン。私たちみたいな新人は、来年の予選シード権を与えて待機させるはずだ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Hmph. They'll probably seed us for next year's qualifiers and put us on hold."
L31_1.m_Talk_ENG = L32_1
L32_1 = "哼，像我們這種菜鳥，應該就是用給我們種子選手資格的方式打發掉吧。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "หืม บางทีพวกเขาอาจจะส่งเราเข้ารอบคัดเลือกในปีหน้าและหยุดเราไว้"
L31_1.m_Talk_THA = L32_1
L32_1 = "Hừm. Giống tân binh bọn tôi, chắc cũng sẽ cho quyền tham gia trực tiếp vòng loại năm sau, rồi bắt đợi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "哼，像我们这样的新人，估计就是给个明年的直接参赛权，然后吊着我们吧。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Hmph. Sie werden uns wahrscheinlich für die Qualifikationsrunde im nächsten Jahr anmelden und vorerst auf Eis legen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Hmph. Ils vont probablement nous inscrire d'office pour les qualifications de l'année prochaine et nous mettre en attente."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
