L34_1 = "CHARADE_ACT4_INTERLUDE1@233#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 5400401
L33_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "UNIT_SURPRISE"
L33_1.m_Face = L34_1
L33_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "네에? 그런 법이 어디있어요?!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ええ？　そんなの、あんまりです！！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Whaaat? How does that even work?!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "什麼？哪有這種事？！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "อะไรนะ? มันทำงานยังไงเนี่ย?!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cái gì? Vậy cũng được hả?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "啊？哪有那样的道理？！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Wie bitte? Wie soll das denn gehen?!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hein ? C'est possible ça ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "CHARADE_ACT4_INTERLUDE1@234#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5400401
L34_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_DESPAIR"
L35_1 = "STAFF_CANARY_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "죄송합니다, 사장님. 이렇게 나올 줄은 몰랐어요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "すみません、社長。こう出てくるとは予想できなかったんです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I'm sorry, Boss. I didn't know they would come at us like this."
L34_1.m_Talk_ENG = L35_1
L35_1 = "對不起，老闆。我沒想到事情會變成這樣。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฉันขอโทษบอส ฉันไม่รู้ว่าพวกเขาจะมาหาเราแบบนี้"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi xin lỗi, Ông Chủ. Tôi không biết chúng sẽ giở trò  với chúng ta như thế."
L34_1.m_Talk_VTN = L35_1
L35_1 = "对不起，老板。我没想到事情会变成这样。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Es tut mir leid, Boss. Ich wusste nicht, dass es so kommen würde."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je suis désolée, monsieur. Je ne m'attendais pas à ça."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "CHARADE_ACT4_INTERLUDE1@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5400401
L35_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "STAFF_CANARY_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "먼저 말씀을 드렸더라면……."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "先にお話ししていたら……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Had I told you sooner..."
L35_1.m_Talk_ENG = L36_1
L36_1 = "如果我提前告訴你……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันน่าจะบอกคุณเร็วกว่านี้..."
L35_1.m_Talk_THA = L36_1
L36_1 = "Nếu tôi nói với ngài sớm hơn ..."
L35_1.m_Talk_VTN = L36_1
L36_1 = "如果我提前告诉你……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Hätte ich es Ihnen bloß schon früher gesagt ..."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Si je vous l'avais dit plus tôt..."
L35_1.m_Talk_FRA = L36_1
