L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 5400401
L37_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Action = "SELECT"
L38_1 = "MARK8"
L37_1.m_ActionStrKey = L38_1
L38_1 = "괜찮네. 애초에 그럴 마음 없었으니."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "大丈夫。そもそもその気はなかったのだからな。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "It's fine. I had no intention to bribe anyone in the first place."
L37_1.m_Talk_ENG = L38_1
L38_1 = "沒事，反正我本來就不打算走後門。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ไม่เป็นไร ผมไม่ได้ตั้งใจจะติดสินบนใครตั้งแต่แรก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Không sao. Tôi vốn không ý định hối lộ bất cứ ai ngay từ đầu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "没关系，因为我本身也没有贿赂的想法。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Schon gut. Ich hatte von Anfang an nicht die Absicht, jemanden zu bestechen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Tout va bien. Je n'avais pas vraiment l'intention de distribuer des pots-de-vin, de toute façon."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
