L41_1 = "STAFF_CANARY_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "아, 네. 카나리아 스쿼드의 스키너입니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あ、はい。カナリア・スクワッドのスキナーです。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Hello? Yes, this is Skinner of Canary Squad."
L40_1.m_Talk_ENG = L41_1
L41_1 = "是，你好，我是金絲雀小隊的史金納。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "สวัสดี? ใช่ นี่คือสกินเนอร์แห่ง หน่วยแคนารี"
L40_1.m_Talk_THA = L41_1
L41_1 = "Alo? Vâng, tôi là Skinner của Tiểu đội Canary."
L40_1.m_Talk_VTN = L41_1
L41_1 = "啊，您好，我是金丝雀小队的斯金纳。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Hallo? Ja, hier spricht Skinner vom Canary Trupp."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Allô ? Oui, je suis bien Skinner de l'escouade Canari."
L40_1.m_Talk_FRA = L41_1
