L42_1 = "STAFF_CANARY_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "네? 지금 누구시라고……."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "はい？　今、どちら様と……？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Excuse me? Who is this again...?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "嗯？你說你找誰……"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอโทษนะ? นี่ใคร...?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Xin lỗi? Ngài là ai ạ...?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "嗯？你说你找谁……"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wie bitte? Wer sind Sie ...?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Oui ? Mais qui êtes-vous...?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "CHARADE_ACT4_INTERLUDE1@242#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 242
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5400401
