L42_1.m_Face = "UNIT_DESPAIR"
L43_1 = "STAFF_CANARY_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "……잠시만요. 금방 바꿔 드리겠습니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……少々お待ちください。すぐにお繋ぎします。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "...Please hold. I'll get him for you."
L42_1.m_Talk_ENG = L43_1
L43_1 = "……請稍等，我馬上把電話轉給他。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "...กรุณาถือสายรอสักครู่ ฉันจะเรียกเขามาคุยกับคุณ"
L42_1.m_Talk_THA = L43_1
L43_1 = "...Xin hãy chờ mày. Tôi sẽ chuyển máy ngay."
L42_1.m_Talk_VTN = L43_1
L43_1 = "……等等，我马上把电话给他。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "... Einen Moment, bitte. Ich reiche das Telefon gleich an ihn weiter."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Un instantn s'il vous plaît... Je vous le passe."
L42_1.m_Talk_FRA = L43_1
