L44_1 = "STAFF_CANARY_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "받아 보셔야겠어요, 사장님."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "電話をお取りください、社長。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I think you need to take this, Boss."
L43_1.m_Talk_ENG = L44_1
L44_1 = "老闆需要接這通電話。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันคิดว่าคุณต้องรับสายนี้ บอส"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ông Chủ ngài cần nghe máy."
L43_1.m_Talk_VTN = L44_1
L44_1 = "您需要接一下电话，老板。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich denke, Sie müssen diesen Anruf annehmen, Boss."
L43_1.m_Talk_DEU = L44_1
L44_1 = "C'est pour vous, monsieur."
L43_1.m_Talk_FRA = L44_1
