L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "아무래도 굉장히 높으신 분 연락인 것 같아서요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "どうやら、相当上の方からの連絡みたいです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "It sounds like someone very important."
L44_1.m_Talk_ENG = L45_1
L45_1 = "好像是高層人士的電話。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เหมือนเป็นคนสำคัญมาก"
L44_1.m_Talk_THA = L45_1
L45_1 = "Có vẻ là ai đó rất quan trọng."
