L48_1 = "늦게 연락드려 죄송합니다, 최고 관리자님."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "遅くなり申し訳ございません、最高管理者。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "My apologies for calling at such a late hour, Supreme Administrator."
L47_1.m_Talk_ENG = L48_1
L48_1 = "抱歉，這麼晚才聯繫您，最高管理者。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ขออภัยที่โทรมาช้าแบบนี้ ผู้บริหารสูงสุด"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi xin lỗi vì đã gọi vào lúc muộn như vậy, Quản Trị Viên Tối Cao."
L47_1.m_Talk_VTN = L48_1
L48_1 = "很抱歉这么晚才联系您，最高管理者。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Es tut mir leid, dass ich Sie zu so später Stunde angerufen habe, Oberster Administrator."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Désolé pour cet appel tardif, Administrateur suprême."
L47_1.m_Talk_FRA = L48_1
