L1_1.m_Pos = "C"
L2_1 = "소식은 전해 들었습니다. 직원들이 건틀렛에서 불미스러운 일에 연루되었다더군요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "話は聞きました。御社の社員がガントレットで芳しくないことに巻き込まれたと。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I heard the news. It seems that your employees were involved in some unfortunate events in the Gauntlet."
L1_1.m_Talk_ENG = L2_1
L2_1 = "事情我都聽說了，您的員工在聖鎧聯賽中捲入一些不愉快的事。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ผมได้ยินข่าว ดูเหมือนว่าพนักงานของคุณจะตกอยู่ในเหตุการณ์ที่โชคร้ายในกอนต์เล็ต"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tôi đã nghe tin. Có vẻ như nhân viên của ngài đã dính vào một số sự kiện không may trong Gauntlet."
L1_1.m_Talk_VTN = L2_1
L2_1 = "事情我都听说了，您的职员们在圣铠上卷入了一些不愉快的事。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ich habe die Nachrichten gehört. Es scheint, dass Ihre Angestellten in einige unglückliche Ereignisse in der Fehde verwickelt waren."
L1_1.m_Talk_DEU = L2_1
L2_1 = "J'ai entendu la nouvelle. On dirait que vos employés sont impliqués dans quelques événements malheureux."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "CHARADE_ACT4_INTERLUDE1@252#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 252
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5400401
L2_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "CHARADE_ADMIN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "룰보다는 성과. 급격한 성장의 대가로 샤레이드가 앓아 온 고질병이죠."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ルールよりは成果。急激な成長の対価として、シャレードが悩まされてきた悪習です。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Results over rules. It is the disease that has plagued Charade for decades, in return for its rapid development."
L2_1.m_Talk_ENG = L3_1
L3_1 = "結果比規則更重要，這是快速發展的代價，也是查雷德的舊疾。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ผลกระทบนอกกฎ โรคนี้เป็นโรคที่เกิดกับ ชาเรด มานานหลายทศวรรษ ในทางตรงกันข้ามกับการพัฒนาที่รวดเร็วของมัน"
L2_1.m_Talk_THA = L3_1
L3_1 = "Kết quả quan trọng hơn quy tắc. Đó là căn bệnh đã đeo bám Charade trong nhiều thập kỷ, đổi lại là sự phát triển nhanh chóng của nơi này."
L2_1.m_Talk_VTN = L3_1
L3_1 = "比起规则更注重成果，这是快速发展的代价，也是查雷德的沉疴痼疾。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Ergebnisse stehen über Regeln. Es handelt sich um eine chronische Krankheit, die Charade aufgrund des schnellen Wachstums bereits seit Jahrzehnten plagt."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Plus que les règles, seul le résultat compte. C'est le prix que Charade a payé pour sa croissance rapide. C'est une maladie chronique qui la tourmente depuis longtemps."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "CHARADE_ACT4_INTERLUDE1@253#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 253
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5400401
L3_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "CHARADE_ADMIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "하지만 3등 시민을 선수로 기용하신 것은 의외였습니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ですが、3等市民を選手として起用されたのは意外でした。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But I must say, it was quite unexpected of you to hire grade 3 citizens."
L3_1.m_Talk_ENG = L4_1
L4_1 = "不過我很意外，您居然會雇傭三等市民作為參賽選手。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แต่ผมต้องบอกว่า มันเป็นเรื่องไม่คาดคิดเลยที่คุณจ้างพลเมืองเกรด 3"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nhưng phải nói rằng, tôi khá bất ngờ khi ngài thuê công dân hạng 3."
L3_1.m_Talk_VTN = L4_1
L4_1 = "不过我很意外，您居然会雇佣三等市民作为参赛选手。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Aber ich muss sagen, es war ziemlich unerwartet von Ihnen, Bürger der 3. Klasse einzustellen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Mais je dois dire que c'était assez inattendu de votre part d'embaucher des citoyens de grade 3."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "CHARADE_ACT4_INTERLUDE1@254#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 254
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5400401
L4_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "CHARADE_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "단순히 건틀릿에서의 성과를 노리신 거라면 원래 직원들을 기용하셔도 됐을 텐데요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "単にガントレットでの成果を狙っているのなら、既存の社員を起用されてもよかったはずですが。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Should you have been aiming for results in the Gauntlet, your other employees would have been more than sufficient."
L4_1.m_Talk_ENG = L5_1
L5_1 = "如果您只是單純地想在聖鎧上取得好成績，那您大可以派原來的員工。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "หากคุณตั้งเป้าที่กอนต์เล็ต มีแค่พนักงานคนอื่นๆ ก็น่าจะเพียงพอแล้ว"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nếu ngài vẫn nhắm đến thành tích trong Gauntlet, nhân viên cũ của ngài sẽ tốt hơn cả."
L4_1.m_Talk_VTN = L5_1
L5_1 = "如果您只是单纯地想在圣铠上取得好成绩，那您大可以启用原来的职员。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Hätten Sie in der Fehde lediglich auf Ergebnisse abgezielt, wären Ihre anderen Angestellten mehr als ausreichend gewesen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Si c'est des résultats que vous recherchiez, vos employés auraient été suffisants."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
