L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "ADMIN_COFFIN_NULL_QM"
L10_1.m_CharStrID = L11_1
L11_1 = "부정행위에 조치를 취할 생각은 없나 보군."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "不正行為に対して措置を取る気はないようだな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I assume you don't plan on taking action for the malfeasance."
L10_1.m_Talk_ENG = L11_1
L11_1 = "看來你無意採取措施打擊作弊行為呢。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ผมคิดว่าคุณไม่ได้กำลังวางแผนประพฤติมิชอบธรรมพวกนี้อยู่นะครับ"
L10_1.m_Talk_THA = L11_1
L11_1 = "Xem ra ngài không định hành động giải quyết việc gian lận."
L10_1.m_Talk_VTN = L11_1
L11_1 = "看来你无意采取措施打击作弊行为呢。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich gehe davon aus, dass Sie nicht vorhaben, wegen des Fehlverhaltens Maßnahmen zu ergreifen."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je suppose que vous n'avez pas l'intention d'engager des poursuites pour cette malversation."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "CHARADE_ACT4_INTERLUDE1@261#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 261
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5400401
L11_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_DESPAIR"
L12_1 = "CHARADE_ADMIN_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "예. 지배층의 불문율을 존중하기 때문이기도 하지만……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "はい。支配階級の不文律を尊重しているためでもありますが……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I'm afraid not. Primarily because I respect the unwritten law of the ruling class..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "是的，部分原因是出於尊重高層的淺規則。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันเกรงว่าจะยาก จริงๆแล้ว ผมเคารพกฎหมายที่ไม่ได้เขียนไว้ในชนชั้นปกครอง..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi sợ là không thể. Chủ yếu là vì tôi cũng tôn trọng luật bất thành văn của giai cấp thống trị..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "是的，因为我也会尊重统治阶层所默认的规定。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "So ist es. Vor allem, weil ich das ungeschriebene Gesetz der herrschenden Klasse respektiere ..."
L11_1.m_Talk_DEU = L12_1
L12_1 = "J'ai bien peur que non. Principalement parce que je respecte la loi non écrite de la classe dirigeante.."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "CHARADE_ACT4_INTERLUDE1@262#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 262
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 5400401
L12_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_IDLE"
L13_1 = "CHARADE_ADMIN_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "무엇보다 당신의 능력을 증명하기에 이번 리그가 좋은 기회라고 판단했습니다."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "何よりあなたの能力を証明するのに、今度のリーグがいい機会であると判断しました。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But moreover, I consider this League to be a good opportunity for you to prove your abilities."
L12_1.m_Talk_ENG = L13_1
L13_1 = "最重要的是，我認為這次聯賽是證明您能力的好機會。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่มากกว่านั้นคือ ผมถือว่าลีกนี้จะเป็นโอกาสที่ดีสำหรับคุณในการพิสูจน์ความสามารถของคุณเองด้วย"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nhưng hơn nữa, tôi coi Giải đấu này là một cơ hội tốt để ngài chứng minh khả năng của mình."
L12_1.m_Talk_VTN = L13_1
L13_1 = "最重要的是，我认为这次联赛是证明您能力的好机会。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Aber darüber hinaus halte ich diese Liga für eine gute Gelegenheit für Sie, Ihre Fähigkeiten unter Beweis zu stellen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Et puis, je considère cette compétition comme une bonne opportunité de prouver de quoi vous êtes capable."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
