L15_1 = "CHARADE_ACT4_INTERLUDE1@264#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 264
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5400401
L14_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Action = "SELECT"
L15_1 = "MARK10"
L14_1.m_ActionStrKey = L15_1
L15_1 = "증명해야 할 필요가 있는 건가?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "証明する必要があるのか？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "And why should I be proving something at all?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "非證明不可嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แล้วทำไมผมต้องพิสูจน์อะไรแบบนี้ด้วยล่ะ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Và tại sao tôi phải chứng minh??"
L14_1.m_Talk_VTN = L15_1
L15_1 = "有必要非得证明吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Und warum sollte ich überhaupt etwas beweisen?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Et pourquoi devrais-je prouver quelque chose ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "CHARADE_ACT4_INTERLUDE1@265#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 265
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5400401
L15_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Action = "MARK"
L16_1 = "MARK10"
L15_1.m_ActionStrKey = L16_1
L16_1 = "CHARADE_ADMIN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "당신은 여태껏 막후에서 많은 문제를 처리해 오셨습니다. 그건 자명한 사실이죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "あなたはこれまで裏で数多くの問題を解決してきました。それは紛れもない事実です。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "All these years, you have been taking care of everything in the dark. That's an undeniable fact."
L15_1.m_Talk_ENG = L16_1
L16_1 = "一直以來您在幕後解決掉很多問題，這是毋庸質疑的事實。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ตลอดหลายปีที่ผ่านมาคุณดูแลทุกอย่างเกี่ยวกับสีดำ นั่นเป็นข้อเท็จจริงที่ปฏิเสธไม่ได้เลยใช่ไหม"
L15_1.m_Talk_THA = L16_1
L16_1 = "Ngài đã luôn xử lý mọi thứ trong bóng tối. Đó là một thực tế không thể phủ nhận."
L15_1.m_Talk_VTN = L16_1
L16_1 = "一直以来您在幕后解决了很多问题，这是毋庸质疑的事实。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "All die Jahre haben Sie sich im Geheimen um alles gekümmert. Das ist eine unbestreitbare Tatsache."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Toutes ces années, vous avez tout géré dans l'ombre. C'est un fait indéniable."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "CHARADE_ACT4_INTERLUDE1@266#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 266
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 5400401
L16_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "CHARADE_ADMIN_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "하지만 당신은 막후에 남는 대신, 전면에 서기로 하셨습니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ですがあなたは裏にいることを辞め、表舞台に立つことになさいました。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "But instead of staying in the dark, you've decided to come forward."
L16_1.m_Talk_ENG = L17_1
L17_1 = "但是現在您選擇站在台前，而不是留在幕後。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่แทนที่จะอยู่ในแต่ในนั้น แต่คุณกลับตัดสินใจที่จะก้าวไปข้างหน้า"
L16_1.m_Talk_THA = L17_1
L17_1 = "Nhưng thay vì ở trong bóng tối, ngài đã quyết định tiến lên phía trước."
L16_1.m_Talk_VTN = L17_1
L17_1 = "但是现在您选择了站在台前，而不是留在幕后。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Aber anstatt hinter den Kulissen zu bleiben, haben Sie sich entschieden, an vorderster Front zu stehen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Mais cette fois, vous avez décidé de vous montrer."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "CHARADE_ACT4_INTERLUDE1@267#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 267
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5400401
L17_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "CHARADE_ADMIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "배후에서 상황을 조종하는 것과 앞에서 사람들을 이끄는 일은 분명 다릅니다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "背後で状況を操ることと、表舞台で人々を導くことは明らかに違います。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Controlling everything from the behind the curtain and being a leader of the people are extremely different."
L17_1.m_Talk_ENG = L18_1
L18_1 = "在背後操控局勢和在台前領導別人是二碼子事。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "การควบคุมทุกอย่างหลังม่านกับการเป็นผู้นำของประชาชนนั้นแตกต่างกันอย่างมาก"
L17_1.m_Talk_THA = L18_1
L18_1 = "Kiểm soát mọi thứ từ sau bức màn và trở thành người lãnh đạo của mọi người là hai chuyện vô cùng khác nhau."
L17_1.m_Talk_VTN = L18_1
L18_1 = "在背后操控局势和在台前领导别人是两码事。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Es gibt einen klaren Unterschied zwischen der Kontrolle einer Situation hinter den Kulissen und der Führung von Menschen an der Front."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Tout contrôler dans l'ombre et être un leader du peuple sont deux choses extrêmement différentes."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "CHARADE_ACT4_INTERLUDE1@268#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 268
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 5400401
L18_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "CHARADE_ADMIN_NULL_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "그러니 그에 걸맞은 능력을 보여 주십시오. 그렇다면 모두가 따를 수 있을 겁니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ですので、それに相応しい能力を見せてください。そうすれば、みんなが従うでしょう。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "So show us that you possess the ability to do so. Should you succeed, you will earn respect from all of us."
L18_1.m_Talk_ENG = L19_1
L19_1 = "所以，請拿出實力證明您自己，大家才能服氣。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "จงแสดงให้เราเห็นว่าคุณมีความสามารถจริงๆ หากคุณทำสำเร็จ คุณจะได้รับความเคารพนับถือจากพวกเราทุกคน"
L18_1.m_Talk_THA = L19_1
L19_1 = "Vì vậy, hãy cho chúng tôi thấy khả năng của ngài. Nếu thành công, ngài sẽ nhận được sự tôn trọng từ tất cả chúng tôi."
L18_1.m_Talk_VTN = L19_1
L19_1 = "所以，请您展示出与之匹配的能力。那么大家就会追随您了。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Zeigen Sie uns also, dass Sie die Fähigkeit dazu besitzen. Sollten Sie Erfolg haben, wird Ihnen der Respekt aller zuteilwerden."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Montrez-nous ce dont vous êtes capable. Vous gagnerez alors notre respect. "
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
