L21_1 = "CHARADE_ACT4_INTERLUDE1@270#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 270
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 5400401
L20_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Action = "SELECT"
L21_1 = "MARK11"
L20_1.m_ActionStrKey = L21_1
L21_1 = "고려는 해 보겠네."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "考えてみよう。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I will consider it."
L20_1.m_Talk_ENG = L21_1
L21_1 = "我考慮一下。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ผมจะเอาไปพิจารณา"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi sẽ cân nhắc."
L20_1.m_Talk_VTN = L21_1
L21_1 = "我考虑一下。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich werde darüber nachdenken."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Je vais prendre cela en considération."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "CHARADE_ACT4_INTERLUDE1@271#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 271
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 5400401
L21_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_LAUGH"
L21_1.m_Action = "MARK"
L22_1 = "MARK11"
L21_1.m_ActionStrKey = L22_1
L22_1 = "CHARADE_ADMIN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "감사합니다. 최고 관리자님."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ありがとうございます。最高管理者。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Thank you, Supreme Administrator."
L21_1.m_Talk_ENG = L22_1
L22_1 = "謝謝您，最高管理者。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ขอบคุณผู้บริหารสูงสุด"
L21_1.m_Talk_THA = L22_1
L22_1 = "Cảm ơn ngài, Quản trị viên tối cao."
L21_1.m_Talk_VTN = L22_1
L22_1 = "谢谢您，最高管理者。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Vielen Dank, Oberster Administrator."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Merci, Administrateur suprême."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "CHARADE_ACT4_INTERLUDE1@272#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 272
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 5400401
