L23_1 = "CHARADE_ADMIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "건투를 빌겠습니다. 그럼."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ご健闘を祈ります。それでは。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I wish you good luck. Farewell."
L22_1.m_Talk_ENG = L23_1
L23_1 = "祝您好運，再見。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ผมขอให้คุณโชคดี  ลาก่อน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Chúc ngài may mắn. Tạm biệt."
L22_1.m_Talk_VTN = L23_1
L23_1 = "祝您好运，再见。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich wünsche Ihnen viel Glück. Auf Wiederhören."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Bonne chance pour votre combat. Au revoir."
L22_1.m_Talk_FRA = L23_1
