L26_1 = "CHARADE_ACT4_INTERLUDE1@275#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 275
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5400401
L25_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_DESPAIR"
L26_1 = "m_StartFXSoundName"
L27_1 = "FX_CUTSCEN_BEEP"
L25_1[L26_1] = L27_1
L26_1 = "CHARADE_ADMIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "기다리게 해서 미안하군."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "待たせてすまないな。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "My apologies for keeping you waiting."
L25_1.m_Talk_ENG = L26_1
L26_1 = "抱歉，久等。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ขออภัยที่ให้รอ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Tôi xin lỗi vì đã để ngài chờ lâu."
L25_1.m_Talk_VTN = L26_1
L26_1 = "抱歉，让你久等了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Entschuldigung, dass ich dich habe warten lassen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Désolé de vous avoir fait attendre de la sorte."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "CHARADE_ACT4_INTERLUDE1@276#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 276
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5400401
L26_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_IDLE"
L27_1 = "CHARADE_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "계속 입을 다물 작정이라면 말리지 않겠지만…."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ずっと黙っているつもりならそれでも構わないが……"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I won't stop you if you wish to stay quiet..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "如果你打算繼續沉默，我也不攔著你……"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ผมจะไม่ห้ามคุณ ถ้าคุณอยากอยู่เงียบๆ..."
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi sẽ không ngăn cản nếu ngài định tiếp tục giữ im lặng ..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "如果你打算继续沉默，我也不拦着你……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich werde dich nicht davon abhalten, weiterhin zu schweigen ..."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je ne peux pas t'empêcher de garder le silence mais..."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "CHARADE_ACT4_INTERLUDE1@277#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 277
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5400401
L27_1.m_CutScenStrID = "CHARADE_ACT4_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "CHARADE_ADMIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "자네에게 당한 이들 중에는 국제 연합군 시절의 내 부하들도 있었어."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "君にやられた者の中には、国際連合軍時代の私の部下たちもいたのだ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "But do remember that among the people you've killed, there are also my men from the Multinational Coalition Force."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不過被你殺死的人中，有我在國際聯合軍隊的部下。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "แต่อย่าลืมว่าในบรรดาคนที่คุณฆ่า มีคนของผมจากกองกำลังผสมข้ามชาติด้วย"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nhưng hãy nhớ rằng trong số những người ngài đã giết, cũng có người của tôi từ Lực Lượng Liên Minh Đa Quốc Gia."
L27_1.m_Talk_VTN = L28_1
L28_1 = "不过被你杀死的人中有我在国际联合军的部下。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Aber denk daran, dass unter den Menschen, die du auf dem Gewissen hast, auch meine Männer von den Multinationalen Vereinten Streitkräften waren."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Rappelle-toi que certains de mes hommes des Forces de la Coalition Internationale font partie des gens que tu as tués."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
